window.TADABBUR_YASIN = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة يس (٣٦)، سورةٌ مكّيّةٌ تُسمّى قلبَ القرآن، محورُها إثباتُ الرسالةِ والتوحيدِ والبعث؛ فيها مثلُ أصحابِ القرية وقصةُ الرجلِ المؤمن، وآياتُ الله في الأرضِ والليلِ والشمسِ والقمرِ والفلك، وأهوالُ البعثِ ونعيمُ الجنّةِ وحوارُ أهلِ النار، وختامٌ بالبعثِ. فيها «إنما أمره إذا أراد شيئا أن يقول له كن فيكون». بُدئت بـ«يس». كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، ونصُّ الآيةِ لا يُكتَب هاهنا بأيدينا، بل يُنقَل عند القراءةِ من مصحفٍ محقَّقٍ مضبوط، صيانةً له من الخطأ."},"n":36,"name":"يس","total_ayahs":83,"audio":[9,12,20,26,36,40,58,65,78,82],"passages":[{"title":"تنزيلُ القرآنِ ورسالةُ النبيّ، وحالُ المعرضين، وكتابةُ الأعمال","range":[1,12],"theme":"القسمُ بالقرآنِ الحكيمِ على رسالةِ النبيِّ وأنه على صراطٍ مستقيم، والقرآنُ تنزيلُ العزيزِ الرحيمِ لإنذارِ الغافلين، وحالُ المعاندين المغلولين العُمي، وأنّ المنتفعَ من اتّبع الذكرَ وخشي الرحمنَ بالغيب، وإحياءُ الموتى وكتابةُ الأعمالِ والآثار","verses":[{"n":1,"reflection":{"text":"«يس»: حروفٌ مقطّعةٌ من الحروفِ التي افتُتِحت بها بعضُ السورِ للتنبيهِ على إعجازِ القرآن، الله أعلمُ بمرادِه بها؛ ففي هذا التسليمُ لله في المتشابه؛ فسلّم لله فيما استأثر بعلمه، ولا تتكلّف تأويلَ ما لم يُبيَّن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله في المتشابه."},"action":{"text":"سلّم لله فيما استأثر بعلمه من المتشابهِ كالحروفِ المقطّعة، ولا تتكلّف القولَ فيها بلا علم؛ واجعل تسليمك لما لم يتبيّن دأبك، مقبلًا على المحكمِ عاملًا به، فذلك سبيلُ الراسخين."}},{"n":2,"reflection":{"text":"«والقرآن الحكيم»: أقسم الله بالقرآنِ المحكمِ المتقنِ الذي لا يأتيه الباطل؛ ففي هذا تعظيمُ القرآنِ والقسمُ به؛ فعظّم القرآنَ الحكيمَ واعمل بمحكمه، فهو كتابٌ متقنٌ حكيمٌ لا خللَ فيه، أقسم الله به لعظمِ شأنه، فاجعله إمامك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ الحكيمِ والعملُ بمحكمه."},"action":{"text":"عظّم القرآنَ الحكيمَ المتقن، فقد أقسم الله به لعظمِ شأنه؛ واعمل بأحكامه، وتلقَّ آياته بالإجلالِ والإذعان؛ فهو كتابٌ محكمٌ لا خللَ فيه ولا تناقض؛ فاجعله إمامك، متدبّرًا لحكمه، مستخرجًا لكنوزه؛ فمن أخذ بالقرآنِ الحكيمِ نال الحكمةَ في قوله وعمله؛ فاجعل القرآنَ ربيعَ قلبك ونورَ صدرك وجلاءَ همّك."}},{"n":3,"reflection":{"text":"«إنك لمن المرسلين»: إنك يا محمدُ لمن المرسلين حقًّا كسائرِ الأنبياء؛ ففي هذا تثبيتُ رسالةِ النبيِّ ﷺ؛ فأيقن بأنّ محمدًا ﷺ رسولُ الله حقًّا، فاتّبعه واعمل بسنّته، فرسالتُه ثابتةٌ بشهادةِ الله، وطاعتُه من طاعةِ الله، فأطعه لتفوز.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ برسالةِ النبيِّ ﷺ واتّباعُه."},"action":{"text":"أيقن يقينًا جازمًا بأنّ محمدًا ﷺ رسولُ الله حقًّا، شهد الله له بالرسالة «إنك لمن المرسلين»؛ فاتّبعه واعمل بسنّته، وقدّم أمره على كلِّ رأيٍ وهوى؛ فطاعتُه من طاعةِ الله، ومحبّتُه من الإيمان؛ فمن اتّبع الرسولَ ﷺ اهتدى، ومن خالفه ضلّ؛ فاجعل اتّباعَ النبيِّ ﷺ ميزانًا لأعمالك؛ فالسعادةُ كلُّها في اتّباعه؛ فعظّمه، واتّبع هديه، وأحبّه أكثرَ من نفسك ومالك وولدك؛ فبذلك تذوق حلاوةَ الإيمان."}},{"n":4,"reflection":{"text":"«على صراط مستقيم»: أنت يا محمدُ على طريقٍ مستقيمٍ لا اعوجاجَ فيه؛ ففي هذا أنّ النبيَّ ﷺ على الحقِّ المستقيم؛ فاسلك الصراطَ المستقيمَ الذي عليه النبيُّ ﷺ، فهو طريقُ الحقِّ الموصلُ إلى الله، فاتّبع هديه لتكون على الصراطِ المستقيم، ولا تنحرف عنه يمنةً ولا يسرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"سلوكُ الصراطِ المستقيمِ الذي عليه النبيُّ ﷺ."},"action":{"text":"اسلك الصراطَ المستقيمَ الذي كان عليه النبيُّ ﷺ، فهو طريقُ الحقِّ الموصلُ إلى الله، لا اعوجاجَ فيه ولا انحراف «على صراط مستقيم»؛ فاتّبع هديه وسنّته في العقيدةِ والعبادةِ والأخلاقِ والمعاملات؛ ولا تنحرف عن الصراطِ يمنةً إلى الغلوِّ ولا يسرةً إلى التفريط؛ فالزم الوسطيةَ والاستقامةَ على أمرِ الله؛ فمن سلك صراطَ النبيِّ ﷺ وصل إلى الله وجنّته؛ ومن انحرف عنه تاه في سبلِ الضلال؛ فاسأل الله دائمًا الهدايةَ إلى الصراطِ المستقيمِ والثباتَ عليه؛ فهو الطريقُ الوحيدُ الموصلُ إلى رضا الله."}},{"n":5,"reflection":{"text":"«تنزيل العزيز الرحيم»: هذا القرآنُ تنزيلٌ من الله العزيزِ الغالبِ الرحيمِ بعباده؛ ففي هذا تقريرُ مصدرِ القرآنِ الإلهيّ؛ فعظّم القرآنَ فهو تنزيلُ العزيزِ الرحيم، واعمل به، فمصدرُه من العزيزِ الذي لا يُغلَب، الرحيمِ الذي أنزله رحمةً بك، فاطمئنَّ إلى أنه حقٌّ ورحمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["العزيز","الرحيم"],"heart_state":{"text":"تعظيمُ القرآنِ تنزيلَ العزيزِ الرحيم."},"action":{"text":"عظّم القرآنَ في قلبك، فهو تنزيلٌ من الله العزيزِ الغالبِ الذي لا يُقهَر، الرحيمِ الذي أنزله رحمةً بعباده «تنزيل العزيز الرحيم»؛ فتلقَّ آياته بالتصديقِ والإذعانِ والعمل؛ واعلم أنّ ما فيه من أوامرَ ونواهٍ صادرٌ عن عزّةٍ وحكمةٍ ورحمة؛ فما أمرك به فلمصلحتك، وما نهاك عنه فلحمايتك؛ فاطمئنَّ إلى أنّ القرآنَ حقٌّ ورحمةٌ من ربّك؛ فاجعله دستورك ونورك؛ فمن عظّم القرآنَ وعمل به نال عزّةَ الدنيا ورحمةَ الآخرة؛ فأقبل عليه تلاوةً وتدبّرًا وعملًا؛ فمصدرُه الإلهيُّ يوجب التعظيمَ والاتّباع."}},{"n":6,"reflection":{"text":"«لتنذر قوما ما أنذر آباؤهم فهم غافلون»: أنزلناه لتنذر قومًا (العربَ) لم يأتهم نذيرٌ قريبٌ من قبلك فهم غافلون عن الحق؛ ففي هذا أنّ إرسالَ النذيرِ رحمةٌ لإيقاظِ الغافلين؛ فاحذر الغفلةَ عن الحقّ، فالنذارةُ جاءتك لتوقظك، فمن غفل عن الآخرةِ حُرِم، فاستيقظ من الغفلةِ بالإنذارِ واتّبع الحق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الغفلةِ عن الحقِّ والاستيقاظُ بالإنذار."},"action":{"text":"احذر الغفلةَ عن الحقِّ وعن الآخرةِ والاستعدادِ لها، فقد أرسل الله النذيرَ رحمةً ليوقظ الغافلين «لتنذر قوما ما أنذر آباؤهم فهم غافلون»؛ فاستيقظ من غفلتك بالإنذارِ والموعظة؛ ولا تدع الدنيا ولذّاتها تُغفلك عن ربّك ولقائه؛ فأكثر من ذكرِ الموتِ والآخرة؛ وتذكّر أنك مسؤولٌ محاسَب؛ فمن استيقظ من الغفلةِ واتّبع الحقَّ نجا، ومن استمرّ في غفلته هلك؛ فاجعل نُذُرَ القرآنِ ومواعظه موقظةً لقلبك من الغفلة؛ فالنذارةُ رحمةٌ بك لتنجو؛ فلا تقابلها بمزيدٍ من الغفلةِ والإعراض؛ بل بالانتباهِ والتوبةِ والعمل."}},{"n":7,"reflection":{"text":"«لقد حق القول على أكثرهم فهم لا يؤمنون»: لقد وجب العذابُ على أكثرِ المعرضين لإصرارهم على الكفر فهم لا يؤمنون؛ ففي هذا أنّ الإصرارَ على الكفرِ يوجب حقَّ العذاب؛ فاحذر الإصرارَ على المعصيةِ والإعراض، فإنه يقود إلى ختمِ القلبِ وحقِّ العذاب، فبادر بالإيمانِ قبل أن يحقَّ عليك القول.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإصرارِ على الكفرِ الموجبِ لحقِّ العذاب."},"action":{"text":"احذر الإصرارَ على الكفرِ والإعراضِ عن الحقّ، فإنّ ذلك يوجب حقَّ العذابِ وختمَ القلب «لقد حق القول على أكثرهم فهم لا يؤمنون»؛ فمن أصرَّ على معصيةٍ أو إعراضٍ عن الحقِّ حتى مات على ذلك حقّ عليه العذاب؛ فبادر بالإيمانِ والتوبةِ قبل أن يحقَّ عليك القولُ ويُختَم على قلبك؛ فلا تسوّف بالرجوعِ إلى الله؛ فكلّما تمادى العبدُ في الإعراضِ قسا قلبه واقترب من الطبعِ عليه؛ فتعاهد قلبك بالإيمانِ والتوبةِ والذكر؛ فمن بادر بالتوبةِ نجا، ومن أصرَّ حتى حقّ عليه القولُ هلك؛ فاغتنم مهلةَ الحياةِ في الرجوعِ إلى الله قبل فواتِ الأوان."}},{"n":8,"reflection":{"text":"«إنا جعلنا في أعناقهم أغلالا فهي إلى الأذقان فهم مقمحون»: إنا جعلنا في أعناقِ المعاندين أغلالًا (مانعةً من الإيمان) بلغت أذقانهم فرفعت رؤوسهم فهم مقمحون (رافعو رؤوسهم لا يخفضونها)؛ ففي هذا تصويرُ إعراضِ المعاندين وكبرهم عن الحقّ؛ فاحذر الكبرَ عن الحقِّ الذي يمنع من قبوله، فالمعاندُ كالمغلولِ لا يستطيع الخضوعَ للحق، فتواضع للحقِّ واخفض رأسك بالإذعانِ له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكبرِ المانعِ من قبولِ الحق، والتواضعُ له."},"action":{"text":"احذر الكبرَ والعنادَ عن قبولِ الحقّ، فإنه كالأغلالِ في الأعناقِ تمنع صاحبها من الخضوعِ للحقِّ والإذعانِ له، فيبقى رافعًا رأسه بالكبرِ لا يخفضه بالتواضع «فهي إلى الأذقان فهم مقمحون»؛ فتواضع للحقِّ واخفض رأسك بالإذعانِ والقبول؛ فالمتكبّرُ عن الحقِّ محرومٌ من الهدى كالمغلولِ المقمح؛ فطهّر قلبك من الكبرِ الذي يصدّ عن الحق؛ واقبل الحقَّ ممّن جاء به كائنًا من كان؛ فمن تواضع للحقِّ اهتدى، ومن استكبر عنه ضلّ؛ فاجعل قلبك منقادًا للحقِّ خاضعًا له؛ فالكبرُ أوّلُ ذنبٍ عُصِي الله به، وهو بابُ الحرمانِ من الهدى؛ فالزم التواضعَ والإذعانَ للحق."}},{"n":9,"reflection":{"text":"«وجعلنا من بين أيديهم سدا ومن خلفهم سدا فأغشيناهم فهم لا يبصرون»، وجعلنا بين أيديهم سدًّا ومن خلفهم سدًّا يمنعانهم من الهدى، فأغشينا أبصارهم فهم لا يبصرون الحق؛ ففي هذا تصويرُ عمى المعاندين عن الحقّ؛ فاحذر أسبابَ العمى عن الحقِّ من الكبرِ والإعراضِ والإصرار، فالمعرضُ يُحال بينه وبين الهدى، فاطلب البصيرةَ من الله ولا تعرض عن آياته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أسبابِ العمى عن الحقّ، وطلبُ البصيرة."},"action":{"text":"احذر أسبابَ العمى عن الحقِّ والحرمانِ من الهدى، من الكبرِ والإعراضِ والإصرارِ على المعصية، فإنها كالسدودِ التي تُحال بين العبدِ وبين الهدى فلا يبصر الحق «فأغشيناهم فهم لا يبصرون»؛ فمن أعرض عن آياتِ الله عوقب بالعمى عنها؛ فاطلب البصيرةَ من الله بالإقبالِ عليه والتواضعِ للحقِّ والتوبةِ من المعاصي؛ ولا تعرض عن آياتِ الله وموعظته؛ فتعاهد قلبك بما يفتح بصيرتك: من الذكرِ والتلاوةِ والطاعةِ والدعاء؛ فمن أقبل على الله فتح بصيرته، ومن أعرض عنه أعماه؛ فاسأل الله أن يريك الحقَّ حقًّا ويرزقك اتّباعه؛ فالبصيرةُ نعمةٌ، والعمى عن الحقِّ عقوبةُ الإعراض؛ فاحذر ما يعميك عن الهدى."}},{"n":10,"reflection":{"text":"«وسواء عليهم أأنذرتهم أم لم تنذرهم لا يؤمنون»، وسواءٌ على هؤلاء المعاندين أأنذرتهم أم لم تنذرهم فإنهم لا يؤمنون لإصرارهم؛ ففي هذا أنّ المعاندَ لا تنفعه النذارة؛ فلا تحزن على من لا تنفعه النذارة، فليس عليك إلا البلاغ، والهدايةُ بيدِ الله، فأدِّ ما عليك ولا تحمل همَّ من أصرّ على الكفر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الحزنِ على من لا تنفعه النذارة، وأداءُ البلاغ."},"action":{"text":"لا تحزن حزنًا يهلكك على المعاندين الذين لا تنفعهم النذارةُ لإصرارهم على الكفر، فسواءٌ عندهم أأنذرتهم أم لم تنذرهم لا يؤمنون «وسواء عليهم أأنذرتهم أم لم تنذرهم لا يؤمنون»؛ فليس عليك إلا البلاغُ والإنذار، والهدايةُ بيدِ الله؛ فأدِّ ما عليك من النصحِ والبلاغ، وكِل أمرهم إلى الله؛ فلا تُتعب قلبك على من عزم على الإعراض؛ فامضِ في دعوتك محتسبًا؛ ووجّه جهدك إلى من يرجى قبوله؛ فالنتيجةُ بيدِ الله لا بيدك؛ فمن أدّى ما عليه برئت ذمّته؛ فاجعل همّك أداءَ الأمانةِ لا ضمانَ الهداية؛ فالله يهدي من يشاء بحكمته وعدله؛ فبلّغ وأنذر، ولا تحمل ما لا يلزمك."}},{"n":11,"reflection":{"text":"«إنما تنذر من اتبع الذكر وخشي الرحمن بالغيب فبشره بمغفرة وأجر كريم»: إنما ينتفع بإنذارك من اتّبع القرآنَ وخشي الرحمنَ في الغيبِ (حيث لا يراه الناس)، فبشّره بمغفرةٍ لذنوبه وأجرٍ كريم؛ ففي هذا أنّ المنتفعَ بالنذارةِ أهلُ اتّباعِ الذكرِ وخشيةِ الله؛ فاتّبع القرآنَ واخشَ الله في السرِّ والعلن، فبذلك تنال المغفرةَ والأجرَ الكريم، فالخشيةُ في الغيبِ علامةُ صدقِ الإيمان.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الرحمن"],"heart_state":{"text":"اتّباعُ القرآنِ وخشيةُ الله في الغيبِ لنيلِ المغفرة."},"action":{"text":"اتّبع القرآنَ (الذكر) واعمل به، واخشَ الرحمنَ في الغيبِ حيث لا يراك أحدٌ من الناس؛ فهذه صفةُ من ينتفع بالإنذارِ ويُبشَّر بالمغفرةِ والأجرِ الكريم «إنما تنذر من اتبع الذكر وخشي الرحمن بالغيب فبشره بمغفرة وأجر كريم»؛ فاجعل خشيتك لله في خلوتك كما في جلوتك؛ فالخشيةُ في الغيبِ (في السرِّ) علامةُ صدقِ الإيمانِ ورسوخه؛ فراقب الله في خلواتك، واترك المعصيةَ حيث لا يراك إلا الله؛ فمن اتّبع القرآنَ وخشي الله في الغيبِ نال المغفرةَ والأجرَ الكريم؛ فاجمع بين اتّباعِ الذكرِ عملًا وخشيةِ الله سرًّا؛ فبهما تكون من المبشَّرين بمغفرةِ الله وكرمه؛ فأبشر أيها المتّبعُ للقرآنِ الخاشي لله بالمغفرةِ والأجرِ الكريم."}},{"n":12,"reflection":{"text":"«إنا نحن نحيي الموتى ونكتب ما قدموا وآثارهم وكل شيء أحصيناه في إمام مبين»: إنا نحن نحيي الموتى للبعث، ونكتب ما قدّموا من أعمال وآثارهم (ما تركوه من أثرٍ حسنٍ أو سيّئ)، وكلَّ شيءٍ أحصيناه في كتابٍ مبين (اللوحِ المحفوظ)؛ ففي هذا إثباتُ البعثِ وكتابةُ الأعمالِ والآثار؛ فاعمل صالحًا واترك أثرًا حسنًا، فأعمالك وآثارك مكتوبةٌ محصاة، فمن ترك أثرًا حسنًا جرى له أجره، ومن ترك أثرًا سيّئًا لحقه وزره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ وترْكُ الأثرِ الحسن، فالأعمالُ والآثارُ محصاة."},"action":{"text":"اعمل الصالحاتِ واترك أثرًا حسنًا في الناس، فإنّ الله يحيي الموتى ويكتب ما قدّموا من أعمالٍ وما تركوه من آثارٍ حسنةٍ أو سيّئة، وكلُّ شيءٍ محصًى في كتابٍ مبين «ونكتب ما قدموا وآثارهم»؛ فاحرص على ترْكِ الآثارِ الحسنةِ التي يجري لك أجرها بعد موتك: كعلمٍ تعلّمه، أو صدقةٍ جاريةٍ، أو ولدٍ صالحٍ تربّيه، أو سنّةٍ حسنةٍ تسنّها؛ واحذر ترْكَ الآثارِ السيّئةِ التي يلحقك وزرها؛ فما تقدّمه من عملٍ وما تتركه من أثرٍ كلُّه مكتوبٌ محصًى عليك؛ فمن سنَّ سنّةً حسنةً فله أجرها وأجرُ من عمل بها، ومن سنَّ سنّةً سيّئةً فعليه وزرها ووزرُ من عمل بها؛ فانظر أيَّ أثرٍ تترك في الناس؛ فاجعل أثرك خيرًا يجري لك بعد رحيلك؛ فالباقياتُ الصالحاتُ خيرٌ عند ربّك."}}]},{"title":"مثلُ أصحابِ القريةِ والرسلِ الثلاثة","range":[13,19],"theme":"ضربُ المثلِ بأصحابِ القرية، وإرسالُ الرسلِ الثلاثةِ وتكذيبُهم، وشبهةُ بشريّةِ الرسلِ وإنكارِ الوحي، واكتفاءُ الرسلِ بشهادةِ الله وأنّ عليهم البلاغَ المبين، وتهديدُ المعاندين وتطيّرُهم، وإبطالُ التطيّر","verses":[{"n":13,"reflection":{"text":"«واضرب لهم مثلا أصحاب القرية إذ جاءها المرسلون»، واضرب لهم مثلًا بأصحابِ القريةِ إذ جاءها المرسلون يدعونهم إلى الله؛ ففي هذا ضربُ المثلِ بأصحابِ القريةِ للعبرة؛ فاعتبر بأمثالِ القرآنِ وقصصه، فهي عبرةٌ لمن اعتبر، وفي قصةِ أصحابِ القريةِ دروسٌ في الدعوةِ والإيمانِ والعناد، فتدبّرها لتنتفع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بأمثالِ القرآنِ وقصصه."},"action":{"text":"اعتبر بأمثالِ القرآنِ وقصصه، فقد ضرب الله مثلًا بأصحابِ القريةِ الذين جاءهم المرسلون، للعبرةِ والاتّعاظ «واضرب لهم مثلا أصحاب القرية إذ جاءها المرسلون»؛ فتدبّر هذه القصةَ وما فيها من دروس: في صبرِ الدعاةِ على التكذيب، وثباتِ المؤمنِ الناصح، وعاقبةِ المعاندين؛ فاجعل قصصَ القرآنِ وأمثاله موعظةً تزيدك إيمانًا وثباتًا؛ فالقصصُ لم تُذكَر للتسلية، بل للعبرةِ والعمل؛ فمن قرأها معتبرًا انتفع، ومن قرأها لاهيًا حُرِم ثمرتها؛ فتأمّل سننَ الله في نصرِ الحقِّ وأهله، وإهلاكِ الباطلِ وأهله؛ فاجعل غايتك من القصصِ الاتّعاظَ والاقتداءَ بالمؤمنين واجتنابَ سبيلِ المعاندين."},"qadiyya":{"title":"قضيّةُ قريةٍ لم يُعيّنها القرآنُ، وميزانِ زيادة العلم","question":"قال الله: ﴿وَاضْرِبْ لَهُمْ مَثَلًا أَصْحَابَ الْقَرْيَةِ إِذْ جَاءَهَا الْمُرْسَلُونَ﴾.\nفالقصّةُ تُساق كلُّها بالأوصاف: قريةٌ لا اسمَ لها، ومرسلون لا أسماءَ لهم، ولا زمانَ ولا نسب.\nوموضعُ الإشكال أنّ النفس تطلب التعيين، فتنصرف إلى ما لم يُذكر عن الذي ذُكر.\nفالقضيّة: **هل الإبهامُ نقصٌ في الخبر يُتمّه البحث؟** ثمّ: ما حكمُ الاشتغال بتعيين ما أبهمه القرآن؟ ثمّ: **بأيّ شيءٍ يُعرف أنّ قولًا زيادةُ علمٍ أو زيادةُ كلام؟**","background":"ولا يستقيم الجوابُ حتّى يُفرَّق بين خبرٍ سُكت فيه عن شيءٍ لأنّ المقصود لا يتوقّف عليه، وخبرٍ لا يُفهم مرادُه إلّا بمعرفته.\n**فالمثلُ إنّما يُضرب للاعتبار، والاعتبارُ يقع بالوصف لا بالاسم.**\nومن أراد أن يعتبر بمكذّبٍ عوقب، لم يزده اسمُ بلده اعتبارًا.\nثمّ قاعدةٌ عامّة: إنّما يُطلب من الدليل بقدر ما يُبنى عليه.\nفما لا يُبنى عليه حكمٌ ولا عمل، لم يكن طلبُه علمًا وإن كثر فيه القيل.","what_happened":"بدأ السعديُّ ببيان المخاطَبين والمقصود من ضرب المثل: «أي: واضرب لهؤلاء المكذبين برسالتك، الرادين لدعوتك، مثلا يعتبرون به، ويكون لهم موعظة إن وفقوا للخير».\nثمّ عيّن المثلَ نفسه: «وذلك المثل: أصحاب القرية، وما جرى منهم من التكذيب لرسل اللّه، وما جرى عليهم من عقوبته ونكاله».\n⭐ ثمّ انتقل إلى مسألة التعيين فقال: «وتعيين تلك القرية، لو كان فيه فائدة، لعينها اللّه، فالتعرض لذلك وما أشبهه من باب التكلف والتكلم بلا علم».\nثمّ جعل الاضطرابَ نفسَه ممّا يُعرف به الطريق، فقال: «ولهذا إذا تكلم أحد في مثل هذا تجد عنده من الخبط والخلط والاختلاف الذي لا يستقر له قرار، ما تعرف به أن طريق العلم الصحيح، الوقوف مع الحقائق، وترك التعرض لما لا فائدة فيه».\n⭐ ثمّ ذكر الثمرةَ وموضعَ وهم الجاهل: «وبذلك تزكو النفس، ويزيد العلم، من حيث يظن الجاهل أن زيادته بذكر الأقوال التي لا دليل عليها، ولا حجة عليها»، ثمّ حاصلَ ذلك الخوض: «ولا يحصل منها من الفائدة إلا تشويش الذهن واعتياد الأمور المشكوك فيها».\nثمّ رجع إلى موضع الحجّة من الآية: «والشاهد أن هذه القرية جعلها اللّه مثلا للمخاطبين».\nثمّ فسّر مجيء المرسلين بما جاءوا به: «من اللّه تعالى يأمرونهم بعبادة اللّه وحده، وإخلاص الدين له، وينهونهم عن الشرك والمعاصي».","the_verdict":"فالحاصلُ أنّ **سكوتَ القرآن عن الاسم خبرٌ، لا فراغ**.\n⭐ وحجّةُ الإمام مبنيّةٌ على أنّ تركَ التعيين ممّن يَقدر عليه ويعلمه دليلٌ على انتفاء الفائدة فيه؛ ولذا قال: «لو كان فيه فائدة، لعينها اللّه». فمن طلب الاسم بعد ذلك فإنّما يطلب ما شُهد له بأنّه لا يفيد.\nوبهذا يظهر جوابُ الأوّل: فالإبهامُ ليس نقصًا يُتمّه البحث. وقد ردّ الإمامُ الأمر إلى موضعه بقوله: «والشاهد أن هذه القرية جعلها اللّه مثلا للمخاطبين»؛ فموضعُ الحجّة كونُها مثلًا، وذلك تامٌّ قبل الاسم.\nوأمّا حكمُه على الاشتغال بالتعيين فسمّاه باسمين: تكلّفًا، وتكلّمًا بلا علم. ولم يقصره على هذه القرية وحدها، بل قال: «فالتعرض لذلك وما أشبهه»، فألحق النظائرَ بها.\n⭐ وموضعُ الدقّة في نظره الثاني أنّه نظر في ثمرة الخوض عند أهله، فوجد «الخبط والخلط والاختلاف الذي لا يستقر له قرار». فالاضطرابُ عنده علامةٌ على الطريق، لا حكمٌ على قولٍ بعينه.\nوأمّا ميزانُ القول الواحد فمأخوذٌ من لفظه: أن يُنظر أله دليلٌ وحجّةٌ أم لا؛ فإنّما جعل مظنّةَ الوهم «ذكر الأقوال التي لا دليل عليها، ولا حجة عليها». فما لا مستند له فهو زيادةُ كلامٍ وإن كثر ناقلوه، وما قام عليه دليلٌ فليس داخلًا في ذمّه.\n⭐ وأدقُّ ما في الموضع قولُه: «من حيث يظن الجاهل»؛ فموضعُ الزيادة عند الجاهل هو بعينه موضعُ النقص عند المحقّق؛ إذ ثمرتُه «تشويش الذهن واعتياد الأمور المشكوك فيها»، ومن اعتاد المشكوك ضعف عنده تمييزُ اليقين.\nوهنا يقع الغلط من جهتين: جهةِ من يظنّ السكوت نقصًا فيملؤه بما لا دليل عليه، وجهةِ من يأخذ الحكم مطلقًا فيردّ كلَّ بيانٍ لم يُنصّ عليه. وقيدُ الإمام ظاهرٌ في قوله: «وترك التعرض لما لا فائدة فيه»؛ فالمتروكُ ما لا فائدة فيه.","for_you":"فأمّا الذي تعمل به فثلاثة:\nالأوّل: إذا مررتَ بمبهمٍ في القرآن فاكتب وصفَه المذكور ودع اسمَه المفقود. خذ هذه الآية اليوم واكتب في سطر: قريةٌ جاءها مرسلون فكذّبوهم فنزل بهم النكال. فإن تمّ لك الاعتبارُ بهذا السطر فقد استغنيتَ عن الاسم بالفعل لا بالدعوى.\nوالثاني: اجعل شرطَ نقلك للقول أن تعرف مستنده. فإذا سمعتَ قولًا فاسأل عن دليله؛ فإن لم يظهر لك فلا تنقله ولا تعُدّه في محفوظك.\nوالثالث: قِس زيادةَ علمك هذا الشهر بعدد المسائل التي تُحسن الاستدلال عليها، لا بعدد الأقوال التي تحفظها ولا تعرف مستندها. واكتب العددين في ورقةٍ واحدة حتّى ترى أيّهما ينمو عندك.","grade":"ma'thur","source":"تفسيرُ السعديّ لضرب المثل ومَن ضُرب لهم («أي: واضرب لهؤلاء المكذبين برسالتك»)، وتعيينُه المثلَ («وذلك المثل: أصحاب القرية»)، وحكمُه في تعيين القرية («وتعيين تلك القرية، لو كان فيه فائدة»)، وجعلُه اضطرابَ الخائضين ممّا يُعرف به الطريق («ولهذا إذا تكلم أحد في مثل هذا»)، وذكرُه الثمرةَ وموضعَ وهم الجاهل («وبذلك تزكو النفس، ويزيد العلم»)، وحاصلُ ذلك الخوض («ولا يحصل منها من الفائدة»)، ورجوعُه إلى موضع الحجّة («والشاهد أن هذه القرية»)، وتفسيرُه مجيءَ المرسلين («من اللّه تعالى يأمرونهم بعبادة اللّه وحده»): كلُّها بنصّها في تفسير السعديّ (٣٦:١٣).","honesty":"وممّا يجب أن يُقال:\nالتفريقُ في التمهيد بين ما سُكت عنه لعدم توقّف المقصود عليه وبين ما يتوقّف عليه، وقولُنا إنّ المثل يُضرب للاعتبار والاعتبارَ يقع بالوصف: تمهيدٌ منّا لتقريب كلامه، لا نصٌّ له.\nوقاعدةُ أنّه إنّما يُطلب من الدليل بقدر ما يُبنى عليه: عبارةٌ رتّبناها نحن، وليست من لفظه.\nوقولُنا إنّ السكوت عن الاسم خبرٌ لا فراغ: عبارةٌ لنا، حاصلُها استنباطٌ من قوله «لو كان فيه فائدة، لعينها اللّه».\nوصياغتُنا حجّتَه على صورة الاستدلال بترك التعيين مع القدرة عليه، وقولُنا إنّ الاضطراب علامةٌ على الطريق لا حكمٌ على آحاد الأقوال، وقولُنا إنّ من اعتاد المشكوك ضعف عنده تمييزُ اليقين: استنباطٌ منّا مبنيٌّ على قوله.\nوقولُنا إنّ موضع الزيادة عند الجاهل هو موضعُ النقص عند المحقّق: صياغةٌ منّا على قوله «من حيث يظن الجاهل» وقوله «تشويش الذهن»، وليست لفظًا له.\nواستخراجُنا ميزانَ القول الواحد من قيده في «الأقوال التي لا دليل عليها»: فهمٌ منّا لمقتضى القيد، وهو ظاهرٌ في لفظه.\nوذكرُنا جهةَ الغلط الثانية، وهي إطلاقُ الحكم في كلّ ما سكت عنه النصّ، تنبيهٌ منّا، وإنّما استندنا فيه إلى قيده هو في «ما لا فائدة فيه».\nوالأفعالُ الثلاثة في آخر القضيّة من عندنا، إنّما هي تطبيقٌ لما قرّره.\nومن رأى أنّا وسّعنا فليردّه."}},{"n":14,"reflection":{"text":"«إذ أرسلنا إليهم اثنين فكذبوهما فعززنا بثالث فقالوا إنا إليكم مرسلون»: إذ أرسلنا إليهم رسولين فكذّبوهما، فقوّيناهما برسولٍ ثالث، فقالوا: إنا إليكم مرسلون من الله؛ ففي هذا صبرُ الرسلِ وتتابعُ الدعوةِ رغمَ التكذيب؛ فاصبر على الدعوةِ ولا تيأس من التكذيب، فالرسلُ صبروا وتتابعوا في الدعوةِ رغمَ الإعراض، فالداعي يبذل ويصبر، ولا يثنيه التكذيب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الدعوةِ وتتابعُها رغمَ التكذيب."},"action":{"text":"اصبر على الدعوةِ إلى الله ولا يثنيك التكذيبُ والإعراض، فقد أرسل الله إلى أهلِ القريةِ رسولين فكذّبوهما، فعزّزهما بثالثٍ ولم يتركهم بلا نذير «فكذبوهما فعززنا بثالث»؛ فالرسلُ صبروا وتتابعوا في الدعوةِ رغمَ الإعراض؛ فالداعي إلى الله يبذل جهده ويصبر على الأذى والتكذيب، ولا يثنيه ذلك عن مواصلةِ الدعوة؛ فاثبت على دعوتك للحقّ، وكرّرها بأساليبَ متنوّعة، ولا تيأس من إعراضِ المعرضين؛ فأجرك على البذلِ والصبرِ لا على النتيجة؛ فاقتدِ بالرسلِ في صبرهم ومصابرتهم؛ فمن صبر على الدعوةِ ولم ييأس نصره الله؛ فالعاقبةُ للصابرين المحتسبين."}},{"n":15,"reflection":{"text":"«قالوا ما أنتم إلا بشر مثلنا وما أنزل الرحمن من شيء إن أنتم إلا تكذبون»: قال أهلُ القرية: ما أنتم إلا بشرٌ مثلنا، وما أنزل الرحمنُ شيئًا من وحي، ما أنتم إلا كاذبون؛ ففي هذا شبهةُ المكذّبين في بشريّةِ الرسلِ وإنكارِ الوحي؛ فلا تستنكر بشريّةَ الرسل، فالله يختار رسله من البشرِ ليكونوا قدوةً، فبشريّةُ الرسولِ لا تنافي رسالته، فلا تجعلها حجّةً لردِّ الحق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ استنكارِ بشريّةِ الرسل، وأنها لا تنافي الرسالة."},"action":{"text":"لا تستنكر بشريّةَ الرسل، ولا تجعلها حجّةً لردِّ رسالتهم، كما فعل المكذّبون الذين قالوا: ما أنتم إلا بشرٌ مثلنا «ما أنتم إلا بشر مثلنا»؛ فالله يختار رسله من البشرِ ليكونوا قدوةً يُقتدى بهم، ويمكن اتّباعهم؛ فبشريّةُ الرسولِ لا تنافي رسالته، بل هي من حكمةِ الله؛ فلو أرسل ملكًا لما أمكن الاقتداءُ به؛ فاحذر أن تردَّ الحقَّ بحجّةِ أنّ من جاء به بشرٌ مثلك؛ فالعبرةُ بصدقِ ما جاء به لا بجنسه؛ فآمن بالرسلِ واتّبعهم، ولا تعاند الحقَّ بشبهاتٍ واهية؛ فمن ردّ الحقَّ بحججٍ باطلةٍ هلك، ومن قبله بدليله نجا؛ فاقبل الحقَّ ممّن جاء به ولو كان بشرًا مثلك."}},{"n":16,"reflection":{"text":"«قالوا ربنا يعلم إنا إليكم لمرسلون»: قال الرسلُ: ربّنا يعلم إنا إليكم لمرسلون حقًّا، فكفى بالله شهيدًا؛ ففي هذا اكتفاءُ الرسلِ بشهادةِ الله على صدقهم؛ فإذا كذّبك الناسُ في حقٍّ أنت عليه فاكتفِ بشهادةِ الله، فهو يعلم صدقك، فمن علم الله صدقه فحسبه ذلك، فلا يهمّك تكذيبُ المكذّبين ما دام الله يعلم صدقك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاكتفاءُ بشهادةِ الله على الصدقِ عند التكذيب."},"action":{"text":"إذا كذّبك الناسُ في حقٍّ أنت عليه، أو اتّهموك بالباطل، فاكتفِ بشهادةِ الله على صدقك، كما قال الرسلُ حين كُذِّبوا: «ربنا يعلم إنا إليكم لمرسلون»؛ فمن علم الله صدقه وحقّه فحسبه ذلك، ولا يضرّه تكذيبُ المكذّبين؛ فاجعل همّك رضا الله وعلمه بصدقك، لا رضا الناسِ وتصديقهم؛ فالله يعلم السرائرَ ويشهد على الحقّ؛ فإذا اطمأنَّ قلبك إلى أنّ الله يعلم صدقك، هان عليك تكذيبُ الخلق؛ فامضِ في الحقِّ واثقًا بعلمِ الله وشهادته؛ فمن كان الله شهيده فلا يبالي بمن كذّبه؛ فاعتمد على شهادةِ الله، ولا تلتفت إلى تكذيبِ المبطلين؛ فحسبك أن يعلم الله صدقك ويشهد لك."}},{"n":17,"reflection":{"text":"«وما علينا إلا البلاغ المبين»، وما علينا إلا التبليغُ الواضحُ للرسالة، وليست الهدايةُ إلينا؛ ففي هذا حصرُ مهمّةِ الرسلِ في البلاغ؛ فأدِّ ما عليك من البلاغِ الواضح، ولا تحمل همَّ ما ليس إليك، فمهمّةُ الداعي البلاغُ لا الهداية، والهدايةُ بيدِ الله، فبلّغ واحتسب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أداءُ البلاغِ الواضح، وعدمُ حملِ همِّ الهداية."},"action":{"text":"أدِّ ما عليك من البلاغِ الواضحِ المبينِ للحقّ، ولا تحمل همَّ ما ليس إليك من هدايةِ القلوب، فإنّ مهمّةَ الداعي البلاغُ لا ضمانُ النتيجة، كما قال الرسل: «وما علينا إلا البلاغ المبين»؛ فبلّغ الحقَّ بوضوحٍ وبيان، ثم كِل أمرَ القبولِ إلى الله؛ فليس عليك إلا الإبلاغُ والإيضاح؛ فلا تُتعب نفسك حسرةً على من أعرض بعد بلاغك؛ فادعُ وبيّن وأحسن، محتسبًا أجرك على الله؛ فمن أدّى البلاغَ برئت ذمّته؛ فاجعل همّك إيضاحَ الحقِّ وتبليغه، لا إكراهَ الناسِ على قبوله؛ فالهدايةُ بيدِ الله؛ فبلّغ واحتسب، وامضِ في طريقك، غيرَ حاملٍ ما لا يلزمك من ضمانِ الهداية."}},{"n":18,"reflection":{"text":"«قالوا إنا تطيرنا بكم لئن لم تنتهوا لنرجمنكم وليمسنكم منا عذاب أليم»: قال أهلُ القرية: تشاءمنا بكم، لئن لم تنتهوا عن دعوتنا لنقتلنّكم رجمًا وليمسنّكم منا عذابٌ أليم؛ ففي هذا تهديدُ المعاندين للدعاةِ وتطيّرهم؛ فلا يثنيك تهديدُ المعاندين ولا تطيّرهم عن الدعوةِ إلى الحقّ، فالمعاندون يهدّدون الدعاةَ ويتشاءمون بهم، فاصبر على أذاهم وامضِ في الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الدعوةِ رغمَ تهديدِ المعاندين وتطيّرهم."},"action":{"text":"لا يثنيك تهديدُ المعاندين ولا تطيّرهم وتشاؤمهم بك عن الدعوةِ إلى الحقّ والثباتِ عليه، كما هدّد أهلُ القريةِ الرسلَ بالرجمِ والعذاب وتطيّروا بهم «لئن لم تنتهوا لنرجمنكم»؛ فاصبر على أذى المعاندين وتهديدهم، وامضِ في الحقِّ غيرَ هيّاب؛ فالتطيّرُ والتشاؤمُ من الباطلِ الذي لا حقيقةَ له، فلا يزعزعك؛ ولا يخفك تهديدُ المبطلين، فالله ناصرك؛ فامضِ في دعوتك متوكّلًا على الله، صابرًا على الأذى؛ فمن ثبت على الحقِّ رغمَ التهديدِ نصره الله؛ فلا تدع تهديدَ المعاندين أو تطيّرهم يصدّك عن أداءِ رسالتك؛ فالعاقبةُ للصابرين الثابتين على الحق."}},{"n":19,"reflection":{"text":"«قالوا طائركم معكم أئن ذكرتم بل أنتم قوم مسرفون»: قال الرسل: شؤمكم من أنفسكم وأعمالكم لا منا، أتتشاءمون لأن ذُكِّرتم بالحق؟ بل أنتم قومٌ مسرفون في الكفرِ والعصيان؛ ففي هذا إبطالُ التطيّرِ ونسبتُه إلى أعمالِ العبد؛ فلا تتطيّر ولا تتشاءم، فالخيرُ والشرُّ بقدرِ الله وبأعمالك، والتطيّرُ وهمٌ باطل، والتذكيرُ بالحقِّ نعمةٌ لا شؤم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إبطالُ التطيّر، ومعرفةُ أنّ التذكيرَ بالحقِّ نعمةٌ لا شؤم."},"action":{"text":"اطرح التطيّرَ والتشاؤمَ بالأشخاصِ أو الأشياءِ أو الأوقات، فإنّ الشؤمَ من أعمالِ العبدِ ومعاصيه لا من غيره، كما ردّ الرسلُ على قومهم: «طائركم معكم»؛ ولا تجعل التذكيرَ بالحقِّ والدعوةَ إليه سببًا للتشاؤمِ والنفور، فذلك إسرافٌ في الباطل «أئن ذكرتم بل أنتم قوم مسرفون»؛ فالتذكيرُ بالحقِّ نعمةٌ ورحمة، لا شؤمٌ ونقمة؛ فإذا ذُكِّرت بآيةٍ أو موعظةٍ فاقبلها بالشكرِ والاتّعاظ، لا بالتشاؤمِ والإعراض؛ فالتطيّرُ وهمٌ باطلٌ من الشرك؛ فإذا وقع في نفسك شيءٌ منه فامضِ متوكّلًا على الله؛ فالخيرُ والشرُّ بقدرِ الله وبكسبِ العبد؛ فلا تنسب مصائبك إلى تطيّرٍ باطل، بل راجع أعمالك، وتُب إلى الله؛ فالتوكّلُ يطرد التطيّر."}}]},{"title":"الرجلُ المؤمنُ الناصح، وشهادتُه وإكرامُه","range":[20,27],"theme":"مبادرةُ الرجلِ المؤمنِ للنصرةِ والدعوةِ إلى اتّباعِ الرسلِ المتجرّدين المهتدين، وتقريرُه عبادةَ الخالقِ وبطلانَ عبادةِ العاجزين، وجهرُه بإيمانه، ونيلُه الجنّةَ ونصحُه لقومه ومغفرةُ الله له وإكرامُه","verses":[{"n":20,"reflection":{"text":"«وجاء من أقصى المدينة رجل يسعى قال يا قوم اتبعوا المرسلين»، وجاء من أقصى المدينةِ رجلٌ مؤمنٌ مسرعًا (لمّا سمع بتكذيبهم الرسل) قال: يا قوم اتّبعوا المرسلين؛ ففي هذا مبادرةُ المؤمنِ للنصرةِ والدعوةِ إلى الحق؛ فبادر إلى نصرةِ الحقِّ والدعوةِ إليه، ولا تسكت عن الحقِّ إذا رأيت الباطلَ يعلو، فالمؤمنُ الصادقُ يسعى في نصرةِ الحقِّ ويدعو إليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ إلى نصرةِ الحقِّ والدعوةِ إليه."},"action":{"text":"بادر إلى نصرةِ الحقِّ والدعوةِ إليه، ولا تسكت عنه إذا رأيت الباطلَ يعلو والحقَّ يُكذَّب، كما بادر الرجلُ المؤمنُ الذي جاء من أقصى المدينةِ يسعى ناصحًا: «يا قوم اتبعوا المرسلين»؛ فالمؤمنُ الصادقُ يسعى في نصرةِ الحقِّ ويدعو إليه بشجاعةٍ وحكمة؛ فلا تكن سلبيًّا ساكتًا عن الحقِّ خوفًا أو كسلًا؛ بل قم بواجبِ الأمرِ بالمعروفِ والنهيِ عن المنكرِ والدعوةِ إلى الله بحسبك؛ فمن نصر الحقَّ نصره الله؛ فاجعل نفسك من الساعين في نصرةِ الحقّ، الداعين إليه، الناصحين لأهلهم وقومهم؛ فالسكوتُ عن الحقِّ عند الحاجةِ إليه تفريط؛ فبادر بالنصحِ والدعوةِ والنصرةِ للحقّ؛ فذلك من علاماتِ صدقِ الإيمان."}},{"n":21,"reflection":{"text":"«اتبعوا من لا يسألكم أجرا وهم مهتدون»: اتّبعوا هؤلاء الرسلَ الذين لا يطلبون منكم أجرًا على دعوتهم، وهم مهتدون في أنفسهم؛ ففي هذا أنّ علامةَ الداعي الصادقِ التجرّدُ عن المطامعِ والاهتداءُ في نفسه؛ فاتّبع من يدعوك إلى الله بلا مطمعٍ دنيويّ، وكن أنت داعيًا متجرّدًا مهتديًا، فالداعي الصادقُ لا يطلب أجرًا، ويكون قدوةً في الهدى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الداعي المتجرّدِ المهتدي، والاقتداءُ به."},"action":{"text":"اتّبع من يدعوك إلى الله وهو متجرّدٌ عن المطامعِ الدنيوية لا يطلب منك أجرًا ولا جزاءً، وهو مهتدٍ في نفسه عاملٌ بما يدعو إليه، كما دلّ الرجلُ المؤمنُ قومه: «اتبعوا من لا يسألكم أجرا وهم مهتدون»؛ فهاتان علامتان للداعي الصادق: التجرّدُ عن المطامع، والاهتداءُ في نفسه؛ فاتّبع من جمعهما؛ وكن أنت كذلك إذا دعوت: متجرّدًا عن العوضِ الدنيويّ، عاملًا بما تدعو إليه، قدوةً في الهدى؛ فالداعي الصادقُ لا يبتغي من دعوته دنيا، ويكون أوّلَ العاملين بما يدعو إليه؛ فمن دعا إلى الله متجرّدًا مهتديًا بُورِك في دعوته؛ فاجعل دعوتك خالصةً لله، واعمل بما تدعو إليه؛ فالقدوةُ الصالحةُ أبلغُ من ألفِ موعظة."}},{"n":22,"reflection":{"text":"«وما لي لا أعبد الذي فطرني وإليه ترجعون»، وأيُّ شيءٍ يمنعني من عبادةِ الذي خلقني وإليه ترجعون جميعًا؟ ففي هذا تقريرُ المؤمنِ لعبادةِ الخالق؛ فاعبد الذي فطرك وخلقك، فمن خلقك هو المستحقُّ لعبادتك، وإليه مرجعك، فكيف تعبد سواه وتترك خالقك؟ فأخلص العبادةَ لمن فطرك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عبادةُ الخالقِ الذي فطرك، وإليه المرجع."},"action":{"text":"اعبد الله الذي فطرك وخلقك، فمن خلقك هو وحده المستحقُّ لعبادتك، وإليه مرجعك ومصيرك، كما قرّر الرجلُ المؤمن: «وما لي لا أعبد الذي فطرني وإليه ترجعون»؛ فكيف تعبد سواه وتترك خالقك ورازقك والذي إليه ترجع؟ فذلك تناقضٌ عجيب؛ فأخلص العبادةَ لله الذي فطرك؛ ولا تصرف شيئًا من عبادتك لغيره؛ فاستحضر أنك مخلوقٌ لله، وأنك راجعٌ إليه للحساب؛ فيحملك ذلك على إفرادِه بالعبادةِ والطاعة؛ فمن عرف أنّ الله خالقه ومرجعه أخلص له العبادة؛ فاجعل حياتك كلَّها عبادةً لمن فطرك؛ فالعبادةُ حقٌّ للخالقِ وحده؛ فلا تعبد إلا من خلقك وإليه ترجع؛ فذلك مقتضى العقلِ والفطرة."}},{"n":23,"reflection":{"text":"«أأتخذ من دونه آلهة إن يردن الرحمن بضر لا تغن عني شفاعتهم شيئا ولا ينقذون»: أأتّخذ من دونِ الله آلهةً عاجزة، إن يردني الرحمنُ بضرٍّ لا تنفعني شفاعتهم شيئًا ولا يقدرون على إنقاذي؟ ففي هذا إبطالُ عبادةِ العاجزين؛ فلا تتّخذ من دونِ الله معبودًا لا يدفع عنك ضرًّا ولا يشفع لك، فالمعبوداتُ من دونِ الله عاجزةٌ لا تنفع ولا تنقذ، فأخلص العبادةَ لله القادرِ وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الرحمن"],"heart_state":{"text":"إبطالُ عبادةِ العاجزين، وإفرادُ الله القادرِ بالعبادة."},"action":{"text":"لا تتّخذ من دونِ الله معبودًا عاجزًا لا يملك لك نفعًا ولا ضرًّا، ولا تدفع عنك شفاعتهم شيئًا إن أراد الله بك ضرًّا، ولا يقدرون على إنقاذك، كما قرّر الرجلُ المؤمن: «إن يردن الرحمن بضر لا تغن عني شفاعتهم شيئا ولا ينقذون»؛ فكيف تعبد عاجزًا لا ينفع ولا يدفع ضرًّا ولا ينقذ؟ فأفرد الله القادرَ بالعبادةِ والدعاء؛ فهو وحده الذي يدفع الضرَّ ويجلب النفع؛ فاصرف عبادتك ورجاءك وتوكّلك إليه وحده؛ فمن تعلّق بغيرِ الله خُذِل أحوجَ ما يكون إليه؛ ومن تعلّق بالله كفاه؛ فلا تجعل بينك وبين الله واسطةً تعبدها أو ترجو شفاعتها من دونه؛ فحقّق التوحيدَ الخالص؛ فالعبادةُ حقٌّ للقادرِ وحده، لا للعاجزين الذين لا يملكون شيئًا."}},{"n":24,"reflection":{"text":"«إني إذا لفي ضلال مبين»: إني إن اتّخذت آلهةً من دونِ الله لأكون في ضلالٍ واضح؛ ففي هذا تقريرُ أنّ الشركَ ضلالٌ مبين؛ فاعلم أنّ الشركَ ضلالٌ واضح، فمن عبد غيرَ الله فهو في ضلالٍ بيّن، فأخلص التوحيدَ لله، واحذر الشركَ فإنه أعظمُ الضلال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ أنّ الشركَ ضلالٌ مبين، وإخلاصُ التوحيد."},"action":{"text":"اعلم أنّ الشركَ بالله ضلالٌ واضحٌ بيّن، فمن عبد غيرَ الله أو اتّخذ من دونه آلهةً فهو في ضلالٍ مبين، كما قرّر الرجلُ المؤمن: «إني إذا لفي ضلال مبين»؛ فأخلص التوحيدَ لله وحده؛ واحذر الشركَ خفيَّه وجليَّه، فإنه أعظمُ الضلالِ وأكبرُ الظلم؛ فلا تصرف شيئًا من العبادةِ لغيرِ الله؛ فمن أشرك بالله فقد ضلّ ضلالًا بعيدًا؛ فحقّق التوحيدَ في قلبك ولسانك وعملك؛ فالتوحيدُ هو الهدى، والشركُ هو الضلال؛ فاعتزَّ بتوحيدك لله، واثبت عليه؛ فهو أصلُ النجاةِ والغايةُ من الخلق؛ فاجعل عبادتك كلَّها لله وحده؛ فمن وحّد الله اهتدى، ومن أشرك ضلّ."}},{"n":25,"reflection":{"text":"«إني آمنت بربكم فاسمعون»: إني آمنتُ بربّكم الذي كفرتم به فاسمعوا إيماني واشهدوا عليه؛ ففي هذا إعلانُ المؤمنِ إيمانه والجهرُ به رغمَ التهديد؛ فأعلن إيمانك بالحقِّ ولا تخفه خوفًا من الناس، فالمؤمنُ الصادقُ يجهر بالحقِّ ولو خالفه الناسُ وهدّدوه، فالثباتُ على الحقِّ والجهرُ به من الشجاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إعلانُ الإيمانِ والجهرُ بالحقِّ رغمَ التهديد."},"action":{"text":"أعلن إيمانك بالحقِّ واجهر به، ولا تخفه خوفًا من الناسِ أو تهديدهم، كما أعلن الرجلُ المؤمنُ إيمانه أمام قومه المعاندين المهدّدين: «إني آمنت بربكم فاسمعون»؛ فالمؤمنُ الصادقُ يجهر بالحقِّ ويثبت عليه ولو خالفه الناسُ وهدّدوه؛ فالثباتُ على الحقِّ والجهرُ به عند الحاجةِ من الشجاعةِ والإيمانِ الصادق؛ فلا تكتم الحقَّ خوفًا من لومِ لائمٍ أو تهديدِ معاند؛ بل قله بشجاعةٍ وحكمة؛ فمن جهر بالحقِّ وثبت عليه أعزّه الله؛ فاجعل خوفك من الله لا من الناس؛ فمن خشي الله لم يخشَ سواه؛ فأعلن إيمانك، واثبت على حقّك، ولا تهبِ المعاندين؛ فالعاقبةُ للصادقين الثابتين، والعزّةُ لمن جهر بالحقِّ واحتسب."}},{"n":26,"reflection":{"text":"«قيل ادخل الجنة قال يا ليت قومي يعلمون»: قيل لهذا المؤمنِ بعد أن قتله قومه: ادخل الجنّة، فقال متمنّيًا الخيرَ لقومه: يا ليت قومي يعلمون؛ ففي هذا كرامةُ المؤمنِ ونصحُه لقومه حتى بعد موته؛ فانصح للناسِ وتمنَّ لهم الخير، فهذا المؤمنُ نصح لقومه حتى بعد أن قتلوه، فالمؤمنُ الصادقُ يحبّ الخيرَ للناسِ ولو أساؤوا إليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"النصحُ للناسِ وتمنّي الخيرِ لهم حتى للمسيئين."},"action":{"text":"انصح للناسِ وتمنَّ لهم الخيرَ والهداية، حتى لمن أساء إليك، مقتديًا بالرجلِ المؤمنِ الذي لمّا قتله قومه وأُدخِل الجنّةَ تمنّى لهم الخيرَ فقال: «يا ليت قومي يعلمون» بما أنا فيه من الكرامةِ ليؤمنوا؛ فالمؤمنُ الصادقُ يحبّ الخيرَ للناسِ ولو أساؤوا إليه؛ فلم يحقد على قومه رغمَ قتلهم له، بل تمنّى لهم الهدايةَ والنجاة؛ فاجعل قلبك سليمًا من الحقدِ والانتقام؛ وانصح للناسِ وادعُ لهم بالهداية؛ فمن أحبّ الخيرَ للناسِ أحبّه الله؛ فقابل الإساءةَ بالإحسان، والحقدَ بالعفو، والعداوةَ بالدعاء؛ فذلك خُلقُ المؤمنين وأهلِ الجنّة؛ فاسلم صدرك للمؤمنين وغيرهم، وتمنَّ لهم الخير؛ فذلك من علاماتِ صفاءِ القلبِ وكمالِ الإيمان."}},{"n":27,"reflection":{"text":"«بما غفر لي ربي وجعلني من المكرمين»: يا ليت قومي يعلمون بما غفر لي ربّي وجعلني من المكرمين في الجنّة؛ ففي هذا ثمرةُ الإيمانِ والثباتِ عليه؛ فاعمل لتنال المغفرةَ والكرامةَ في الجنّة، فهذا المؤمنُ نال المغفرةَ والإكرامَ بثباته على الحقّ، فالثباتُ على الإيمانِ حتى الموتِ سبيلُ المغفرةِ والكرامة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الإيمانِ حتى الموتِ لنيلِ المغفرةِ والكرامة."},"action":{"text":"اثبت على الإيمانِ والحقِّ حتى الموت، فبذلك تنال المغفرةَ والكرامةَ في الجنّة، كما نال الرجلُ المؤمنُ ذلك بثباته على الحقِّ حتى قُتِل، فتمنّى أن يعلم قومه «بما غفر لي ربي وجعلني من المكرمين»؛ فثمرةُ الإيمانِ والثباتِ عليه المغفرةُ والإكرام؛ فاجعل غايتك الثباتَ على دينك حتى تلقى الله؛ ولا تفرّط في إيمانك مهما اشتدّت المحن؛ فمن ثبت على الحقِّ ومات عليه نال المغفرةَ والكرامة؛ فاسأل الله الثباتَ على دينه حتى الممات؛ واعمل لتكون من المكرمين في جنّته؛ فالكرامةُ الأبديةُ لمن آمن وثبت وصبر؛ فبادر بالأعمالِ الصالحة، واثبت على الإيمان؛ فالعاقبةُ الحسنةُ لمن ختم له بالإيمانِ والعملِ الصالح؛ فاطلب حسنَ الخاتمةِ بالاستقامةِ والثبات."}}]},{"title":"هلاكُ القريةِ والحسرةُ على العباد، والاعتبارُ بالأمم","range":[28,32],"theme":"هلاكُ قومِ المؤمنِ بصيحةٍ واحدةٍ وهوانُهم على الله، والتحسّرُ على العبادِ المستهزئين بالرسل، والاعتبارُ بالأممِ الهالكةِ التي لا ترجع، وأنّ الخلقَ جميعًا محضَرون للحساب","verses":[{"n":28,"reflection":{"text":"«وما أنزلنا على قومه من بعده من جند من السماء وما كنا منزلين»، وما أنزلنا على قومِ هذا المؤمنِ بعد قتلهم إياه من جندٍ من السماءِ لإهلاكهم، وما كنا محتاجين لإنزالِ جندٍ لإهلاكهم؛ ففي هذا هوانُ المكذّبين على الله؛ فاعلم أنّ إهلاكَ الظالمين يسيرٌ على الله لا يحتاج جندًا، فلا يغرّنك قوّةُ الظالمين، فالله يهلكهم بأدنى سبب، فالأمرُ كلُّه بيدِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ هوانِ المكذّبين على الله، وأنّ إهلاكهم يسير."},"action":{"text":"اعلم أنّ إهلاكَ الظالمين المكذّبين يسيرٌ على الله، لا يحتاج إلى إنزالِ جندٍ من السماء، فقد أهلك الله قومَ المؤمنِ بصيحةٍ واحدةٍ دون حاجةٍ لجيوش «وما أنزلنا على قومه من بعده من جند من السماء»؛ فالمكذّبون هيّنون على الله، لا يعجزونه ولا يحتاج لإهلاكهم عناءً؛ فلا يغرّنك قوّةُ الظالمين وكثرتهم، فالله يهلكهم بأدنى سبب متى شاء؛ فالأمرُ كلُّه بيدِ الله؛ فاطمئنَّ إلى أنّ الله ناصرٌ للحقِّ وأهله، مهلكٌ للباطلِ وأهله؛ فلا تهبِ الظالمين مهما بلغت قوّتهم؛ فقوّتهم لا تساوي شيئًا أمام قدرةِ الله؛ فتوكّل على الله، وثِق بأنّ العاقبةَ للمؤمنين؛ فمن أيقن بهوانِ الظالمين على الله لم يخفهم ولم يغترَّ بقوّتهم؛ فالنصرُ والإهلاكُ بيدِ الله وحده."}},{"n":29,"reflection":{"text":"«إن كانت إلا صيحة واحدة فإذا هم خامدون»: ما كانت إلا صيحةً واحدةً أهلكتهم فإذا هم هامدون موتى؛ ففي هذا سرعةُ هلاكِ المكذّبين بأدنى سبب؛ فاعتبر بسرعةِ هلاكِ الظالمين، فبصيحةٍ واحدةٍ خمدوا، فلا يغرّنك إمهالُ الله للظالمين، فإذا أخذهم أخذهم بغتةً وبأيسرِ سبب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بسرعةِ هلاكِ الظالمين بأدنى سبب."},"action":{"text":"اعتبر بسرعةِ هلاكِ الظالمين المكذّبين، فما كان إهلاكهم إلا بصيحةٍ واحدةٍ خمدوا بها وصاروا موتى هامدين «إن كانت إلا صيحة واحدة فإذا هم خامدون»؛ فلا يغرّنك إمهالُ الله للظالمين وطولُ بقائهم، فإذا أخذهم أخذهم بغتةً وبأيسرِ سبب؛ فقوّتهم وكثرتهم لا تنفعهم أمام أمرِ الله؛ فاحذر الظلمَ والتكذيبَ فعاقبتُهما الهلاكُ السريع؛ ولا تأمن مكرَ الله وأنت مقيمٌ على المعصية؛ فالله يمهل ولا يهمل؛ فإذا جاء أمرُه لم يتأخّر؛ فبادر بالتوبةِ والإيمانِ قبل أن يفاجئك أمرُ الله؛ فمن اعتبر بمصارعِ الظالمين تجنّب سبيلهم؛ فالعاقبةُ للمؤمنين، والهلاكُ السريعُ للمكذّبين؛ فاتّعظ بسرعةِ أخذِ الله للظالمين، ولا تغترَّ بإمهاله."}},{"n":30,"reflection":{"text":"«يا حسرة على العباد ما يأتيهم من رسول إلا كانوا به يستهزئون»: يا حسرةً وندامةً على العبادِ المكذّبين، ما يأتيهم رسولٌ إلا استهزؤوا به؛ ففي هذا التحسّرُ على المكذّبين المستهزئين بالرسل؛ فاحذر الاستهزاءَ بالرسلِ وبالحقّ، فعاقبتُه الحسرةُ والندامة، وعظّم الرسلَ وما جاؤوا به، فالمستهزئُ بالحقِّ يتحسّر يومَ القيامةِ حين لا ينفع التحسّر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاستهزاءِ بالرسلِ والحقّ، فعاقبتُه الحسرة."},"action":{"text":"احذر الاستهزاءَ بالرسلِ وبالحقِّ وبشيءٍ من الدين، فإنّ عاقبةَ ذلك الحسرةُ والندامةُ يومَ القيامة، فقد تحسّر الله على العبادِ المكذّبين الذين كلّما جاءهم رسولٌ استهزؤوا به «يا حسرة على العباد ما يأتيهم من رسول إلا كانوا به يستهزئون»؛ فعظّم الرسلَ وما جاؤوا به من الحقّ؛ ولا تسخر من الدينِ ولا من الدعاةِ إليه؛ فالاستهزاءُ بالحقِّ من أعظمِ الجرائمِ الموجبةِ للحسرةِ والعذاب؛ فراقب لسانك وقلبك أن يقعا في شيءٍ من الاستهزاءِ بالدين؛ ولا تجالس المستهزئين؛ فمن استهزأ بالحقِّ تحسّر يومَ القيامةِ حين لا ينفع التحسّر؛ فعظّم شعائرَ الله وأحكامه ورسله؛ فالمستهزئُ بالحقِّ خاسرٌ نادم، والمعظّمُ له فائزٌ سالم؛ فاحذر أن تكون ممّن يتحسّر يومَ القيامةِ على استهزائه بالحق."}},{"n":31,"reflection":{"text":"«ألم يروا كم أهلكنا قبلهم من القرون أنهم إليهم لا يرجعون»: ألم يروا كم أهلكنا قبلهم من الأمم، وأنّ أولئك الهالكين لا يرجعون إليهم في الدنيا؟ ففي هذا الاعتبارُ بالأممِ الهالكة؛ فاعتبر بمن أهلكهم الله قبلك، فهم لم يرجعوا، فكذلك أنت راحلٌ لا ترجع، فبادر بالعملِ قبل الرحيل، فالموتُ نهايةُ كلِّ حيّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بالأممِ الهالكةِ التي لا ترجع، والمبادرةُ بالعمل."},"action":{"text":"اعتبر بمن أهلكهم الله من الأممِ والقرونِ قبلك، فقد رحلوا ولا يرجعون إلى الدنيا «ألم يروا كم أهلكنا قبلهم من القرون أنهم إليهم لا يرجعون»؛ فكذلك أنت راحلٌ عن هذه الدنيا لا ترجع إليها؛ فبادر بالعملِ الصالحِ قبل الرحيل؛ ولا تغترَّ بطولِ البقاء؛ فكلُّ من سبقك رحل ولم يرجع، وأنت لاحقٌ بهم؛ فاعمل لآخرتك عملَ من يعلم أنه مفارقٌ للدنيا لا محالة؛ واتّعظ بمصارعِ الأممِ الهالكة؛ فمن اعتبر بغيره سلم؛ فاجعل من رحيلِ الأممِ قبلك موعظةً تحملك على الاستعدادِ للرحيل؛ فالموتُ نهايةُ كلِّ حيّ؛ والموفَّقُ من تزوّد لآخرته قبل أن يُفاجأ بالأجل؛ فلا تسوّف بالعمل، فالرحيلُ قريب، والرجعةُ مستحيلة؛ فبادر بالتوبةِ والعملِ الصالح."}},{"n":32,"reflection":{"text":"«وإن كل لما جميع لدينا محضرون»، وما كلُّ الأممِ إلا جميعٌ محضَرون لدينا يومَ القيامةِ للحساب؛ ففي هذا تقريرُ حشرِ الخلقِ جميعًا للحساب؛ فاستعدَّ ليومِ الحشرِ الذي يُحضَر فيه الخلقُ جميعًا، فكلُّ نفسٍ محضَرةٌ للحساب، فاعمل لذلك اليوم، ولا تظنَّ أنك متروكٌ سدًى، فالكلُّ محضَرٌ محاسَب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومِ الحشرِ الذي يُحضَر فيه الخلقُ للحساب."},"action":{"text":"استعدَّ ليومِ الحشرِ العظيم، الذي يُحضَر فيه الخلقُ كلُّهم جميعًا بين يدي الله للحساب، فما من نفسٍ إلا وهي محضَرةٌ محاسَبة «وإن كل لما جميع لدينا محضرون»؛ فاعمل لذلك اليومِ عملَ من يوقن أنه محضَرٌ محاسَبٌ على كلِّ صغيرةٍ وكبيرة؛ ولا تظنَّ أنك متروكٌ سدًى لا تُحاسَب؛ فكلُّ الخلقِ سيُجمَعون ويُحضَرون؛ فبادر بالتوبةِ والعملِ الصالحِ قبل ذلك اليوم؛ فاستحضر أنك واقفٌ بين يدي الله، مسؤولٌ عن عملك؛ فيحملك ذلك على المراقبةِ والاستعداد؛ فمن أيقن بالحشرِ والحسابِ عمل له، ومن غفل عنه فرّط؛ فاجعل استحضارَ يومِ الحشرِ حاديًا لك إلى الطاعةِ وزاجرًا عن المعصية؛ فالكلُّ محضَرٌ محاسَب؛ فاعمل لذلك المشهدِ العظيم."}}]},{"title":"آياتُ الله في الأرضِ والنباتِ والليلِ والشمسِ والقمرِ والفلك","range":[33,44],"theme":"إحياءُ الأرضِ الميتةِ وإخراجُ الحبِّ والثمار، وتسبيحُ خالقِ الأزواج، وآيةُ الليلِ والنهار، وجريُ الشمسِ والقمرِ بتقدير، وإحكامُ النظامِ الكونيّ، ونعمةُ الفلكِ ووسائلِ النقلِ والنجاة، وأنّ البقاءَ رحمةٌ ومتاعٌ إلى حين","verses":[{"n":33,"reflection":{"text":"«وآية لهم الأرض الميتة أحييناها وأخرجنا منها حبا فمنه يأكلون»، وعلامةٌ لهم على البعثِ الأرضُ الميتةُ أحييناها بالمطر وأخرجنا منها حبًّا فمنه يأكلون؛ ففي هذا الاستدلالُ بإحياءِ الأرضِ على البعثِ وعلى نعمةِ الرزق؛ فتأمّل إحياءَ الأرضِ الميتةِ وإخراجَ الحبِّ منها، لتوقن بالبعثِ وتشكر نعمةَ الرزق، فمن أحيا الأرضَ يحيي الموتى، ومن أطعمك يستحقّ شكرك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستدلالُ بإحياءِ الأرضِ على البعث، وشكرُ نعمةِ الرزق."},"action":{"text":"تأمّل الأرضَ الميتةَ كيف يحييها الله بالمطرِ فتخضرّ، ويخرج منها الحبَّ الذي تأكلون منه؛ فذلك آيةٌ على البعثِ (فمن أحيا الأرضَ يحيي الموتى)، ونعمةٌ في الرزق «وآية لهم الأرض الميتة أحييناها وأخرجنا منها حبا فمنه يأكلون»؛ فاجمع بين أمرين: رسّخ يقينك بالبعثِ بالنظرِ في إحياءِ الأرض، واشكر الله على نعمةِ الطعامِ الذي يخرجه لك من الأرض؛ فكلّما رأيت زرعًا أو أكلت طعامًا فتذكّر قدرةَ الله على البعثِ ونعمته عليك بالرزق؛ فمن تأمّل آياتِ الله في الأرضِ ازداد يقينًا وشكرًا؛ فاجعل نظرك في الكونِ نظرَ إيمانٍ وشكر."}},{"n":34,"reflection":{"text":"«وجعلنا فيها جنات من نخيل وأعناب وفجرنا فيها من العيون»، وجعلنا في الأرضِ بساتينَ من نخيلٍ وأعناب، وفجّرنا فيها من العيونِ لسقيها؛ ففي هذا تعدادُ نعمِ الله في الثمارِ والماء؛ فتأمّل نعمَ الله في البساتينِ والعيون، واشكره عليها، فمن أنبت لك الثمارَ وفجّر لك العيونَ يستحقّ شكرك، فاجعل النعمَ سبيلًا للشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في نعمِ الثمارِ والعيون، وشكرُ الله عليها."},"action":{"text":"تأمّل نعمَ الله في الأرض: كيف جعل فيها بساتينَ من نخيلٍ وأعناب، وفجّر فيها العيونَ لسقيها وشربكم «وجعلنا فيها جنات من نخيل وأعناب وفجرنا فيها من العيون»؛ فاشكر الله على هذه النعمِ المتعدّدة: من الثمارِ اللذيذةِ والماءِ العذب؛ فقابل نعمَ الله بالحمدِ والطاعةِ لا بالكفرانِ والغفلة؛ فكلّما أكلت ثمرةً أو شربت ماءً فتذكّر منعمها واشكره؛ فمن تأمّل آياتِ الله في نعمه وشكرها زاده الله؛ فاجعل النعمَ المسخّرةَ لك وسيلةً لشكرِ المنعمِ وطاعته؛ فالشكرُ يستبقي النعمَ ويستجلب المزيد، والكفرانُ يمحقها؛ فلا تنسَ المنعمَ عند التنعّمِ بنعمه؛ بل ازدد به قربًا وشكرًا."}},{"n":35,"reflection":{"text":"«ليأكلوا من ثمره وما عملته أيديهم أفلا يشكرون»: ليأكلوا من ثمرِ ما ذكر، والحال أنّ أيديهم ما عملته بل الله أنشأه، أفلا يشكرون الله على هذه النعم؟ ففي هذا الحثُّ على شكرِ الله على نعمِه؛ فاشكر الله على ما رزقك من الثمارِ والنعم، واعلم أنها من فضلِ الله لا من صنعك، فمن أنعم عليك يستحقّ شكرك، فقلّةُ الشكرِ نقصٌ يُذَمّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ الله على نعمِه، ونسبتُها إليه لا إلى النفس."},"action":{"text":"اشكر الله على ما رزقك من الثمارِ والنعمِ التي تأكل منها، واعلم أنها من فضلِ الله وإنشائه لا من صنعِ يديك «ليأكلوا من ثمره وما عملته أيديهم أفلا يشكرون»؛ فلا تنسب النعمَ إلى جهدك وحده، بل انسبها إلى الله المنعمِ المتفضّل؛ فأنت تأخذ بالأسبابِ والله هو الذي ينبت ويرزق؛ فاشكر الله شكرًا يليق بنعمه: بالقلبِ اعترافًا، وباللسانِ حمدًا، وبالجوارحِ طاعة؛ فقلّةُ الشكرِ نقصٌ يُذَمّ، وكثرتُه سببٌ للمزيد؛ فقابل كلَّ نعمةٍ بشكر؛ فمن شكر الله على نعمه حفظها وزاده، ومن كفرها عرّضها للزوال؛ فلا تكن من الغافلين المقصّرين في الشكر؛ بل كن من الشاكرين الذاكرين لفضلِ الله؛ فالشكرُ قيدُ النعمِ الموجودةِ وصيدُ المفقودة."}},{"n":36,"reflection":{"text":"«سبحان الذي خلق الأزواج كلها مما تنبت الأرض ومن أنفسهم ومما لا يعلمون»: تنزّه الله الذي خلق الأصنافَ والأنواعَ كلَّها أزواجًا: ممّا تنبت الأرضُ، ومن أنفسهم (ذكرًا وأنثى)، وممّا لا يعلمون من المخلوقات؛ ففي هذا تسبيحُ الله على خلقه الأزواجَ وتنوّعَ خلقه؛ فسبّح الله وعظّمه على بديعِ خلقه الأزواجَ في النباتِ والإنسانِ وما لا نعلم، فمن تأمّل تنوّعَ خلقِ الله سبّحه وعظّمه، فاجعل تسبيحَ الله دأبك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تسبيحُ الله وتعظيمُه على خلقه الأزواجَ وتنوّعِ خلقه."},"action":{"text":"سبّح الله ونزّهه وعظّمه على بديعِ خلقه، فهو الذي خلق الأزواجَ (الأصنافَ) كلَّها: ممّا تنبت الأرضُ من النبات، ومن أنفسكم ذكرًا وأنثى، وممّا لا تعلمون من المخلوقاتِ التي لم تُكشَف بعد «سبحان الذي خلق الأزواج كلها مما تنبت الأرض ومن أنفسهم ومما لا يعلمون»؛ فتأمّل تنوّعَ خلقِ الله وإتقانه؛ واجعل ذلك سبيلًا لتسبيحِ الله وتعظيمه؛ فكلّما رأيت مخلوقًا فسبّح خالقه؛ فالتسبيحُ تنزيهٌ لله وعبادةٌ عظيمة؛ فاعمر لسانك وقلبك بتسبيحِ الله؛ فمن تأمّل بديعَ صنعِ الله في الأزواجِ والأصنافِ سبّحه وعظّمه وأحبّه؛ فالكونُ كلُّه يسبّح بحمدِ الله؛ فكن من المسبّحين المعظّمين لخالقهم؛ فالتسبيحُ يطهّر القلبَ ويقرّب من الله."}},{"n":37,"reflection":{"text":"«وآية لهم الليل نسلخ منه النهار فإذا هم مظلمون»، وعلامةٌ لهم على قدرةِ الله الليلُ نُخرِج منه النهارَ (نكشفه عنه) فإذا هم في ظلمة؛ ففي هذا آيةُ تعاقبِ الليلِ والنهار؛ فتأمّل آيةَ الليلِ والنهارِ وتعاقبهما بقدرةِ الله، فمن دبّر هذا النظامَ البديعَ يستحقّ العبادة، فاعتبر بتعاقبِ الليلِ والنهارِ على عظمةِ الخالق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في آيةِ تعاقبِ الليلِ والنهارِ على قدرةِ الله."},"action":{"text":"تأمّل آيةَ الله في الليلِ والنهار، كيف يسلخ الله النهارَ من الليلِ (يكشفه عنه) فإذا الناسُ في ظلمةٍ بعد النور «وآية لهم الليل نسلخ منه النهار فإذا هم مظلمون»؛ فهذا التعاقبُ البديعُ بين الليلِ والنهارِ آيةٌ على قدرةِ الله وحكمته وتدبيره؛ فمن دبّر هذا النظامَ العظيمَ بهذا الإحكامِ يستحقّ أن يُعبَد وحده؛ فاعتبر بتعاقبِ الليلِ والنهارِ على عظمةِ الخالقِ وقدرته؛ واشكر نعمةَ الله في جعلِ الليلِ للسكونِ والنهارِ للمعاش؛ فكلّما جاء ليلٌ أو نهارٌ فتذكّر عظمةَ مدبّرهما؛ فمن تأمّل آياتِ الله في الكونِ ازداد إيمانًا وتعظيمًا؛ فاجعل نظرك في تعاقبِ الليلِ والنهارِ نظرَ اعتبارٍ يقودك إلى تعظيمِ الله وعبادته."}},{"n":38,"reflection":{"text":"«والشمس تجري لمستقر لها ذلك تقدير العزيز العليم»، والشمسُ تجري إلى مستقرٍّ لها (نهايةٍ محدّدة)، ذلك تقديرُ العزيزِ العليم؛ ففي هذا آيةُ جريِ الشمسِ بتقديرِ الله؛ فتأمّل جريَ الشمسِ بنظامٍ دقيقٍ بتقديرِ الله، فمن قدّر هذا النظامَ المحكمَ هو العزيزُ العليم، فاعبده وحده، فالكونُ يجري بتقديرِ الله الحكيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العزيز","العليم"],"heart_state":{"text":"التأمّلُ في جريِ الشمسِ بتقديرِ الله العزيزِ العليم."},"action":{"text":"تأمّل آيةَ الله في الشمسِ كيف تجري في فلكها إلى مستقرٍّ لها بنظامٍ دقيقٍ محكم، ذلك تقديرُ الله العزيزِ العليم «والشمس تجري لمستقر لها ذلك تقدير العزيز العليم»؛ فهذا الجريُ المنتظمُ للشمسِ آيةٌ على قدرةِ الله وحكمته وعلمه؛ فمن قدّر هذا النظامَ الكونيَّ المحكمَ هو العزيزُ الغالبُ الذي لا يُقهَر، العليمُ الذي أحاط بكلِّ شيء؛ فاعبده وحده وعظّمه؛ فالكونُ كلُّه يجري بتقديرِ الله وتدبيره؛ فمن تأمّل انتظامَ الكونِ ودقّةَ نظامه عرف عظمةَ مدبّره وحكمته؛ فاجعل نظرك في آياتِ الله الكونيةِ سبيلًا لتعظيمه وعبادته؛ فالشمسُ والقمرُ والنجومُ كلُّها جنودٌ لله تجري بأمره؛ فسبّح العزيزَ العليمَ الذي أتقن كلَّ شيء."}},{"n":39,"reflection":{"text":"«والقمر قدرناه منازل حتى عاد كالعرجون القديم»، والقمرَ قدّرناه منازلَ (يتنقّل فيها) حتى يعود في آخرِ الشهرِ دقيقًا منحنيًا كعِذْقِ النخلةِ العتيق؛ ففي هذا آيةُ تقديرِ منازلِ القمر؛ فتأمّل تقديرَ الله لمنازلِ القمرِ التي بها تُعرَف الشهورُ والأوقات، فمن قدّر هذا يستحقّ العبادة، فاشكر نعمةَ توقيتِ الأزمانِ بالقمر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في تقديرِ منازلِ القمرِ ونعمةِ توقيتِ الأزمان."},"action":{"text":"تأمّل آيةَ الله في القمرِ كيف قدّر له منازلَ يتنقّل فيها كلَّ ليلة، حتى يعود في آخرِ الشهرِ دقيقًا منحنيًا كعِذْقِ النخلةِ اليابسِ العتيق «والقمر قدرناه منازل حتى عاد كالعرجون القديم»؛ فهذا التقديرُ الدقيقُ لمنازلِ القمرِ آيةٌ على حكمةِ الله وقدرته؛ وبه تُعرَف الشهورُ والأوقاتُ والمواقيتُ للعباداتِ والمعاملات؛ فاشكر نعمةَ الله في توقيتِ الأزمانِ بالقمرِ والشمس؛ فمن قدّر هذا النظامَ البديعَ يستحقّ العبادةَ والشكر؛ فتأمّل حكمةَ الله في خلقِ القمرِ وتقديرِ منازله؛ فكلّما رأيت القمرَ في منازله فتذكّر عظمةَ خالقه وحكمته؛ فاجعل نظرك في آياتِ الله الكونيةِ سبيلًا لتعظيمه وشكره وعبادته؛ فالكونُ كتابٌ مفتوحٌ يدلّ على الله."}},{"n":40,"reflection":{"text":"«لا الشمس ينبغي لها أن تدرك القمر ولا الليل سابق النهار وكل في فلك يسبحون»: لا الشمسُ يمكنها أن تلحق القمرَ فتزاحمه، ولا الليلُ يسبق النهارَ، وكلٌّ (الشمسُ والقمرُ والكواكب) في فلكٍ يجري؛ ففي هذا آيةُ إحكامِ النظامِ الكونيّ؛ فتأمّل إحكامَ النظامِ الكونيِّ الذي لا يختلّ، فكلٌّ يسير في مداره بدقّةٍ بأمرِ الله، فمن أحكم هذا النظامَ يستحقّ العبادة، فاعبد المدبّرَ الحكيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في إحكامِ النظامِ الكونيِّ الذي لا يختلّ."},"action":{"text":"تأمّل إحكامَ النظامِ الكونيِّ الذي أبدعه الله: فالشمسُ لا تدرك القمرَ ولا تزاحمه، والليلُ لا يسبق النهارَ، وكلٌّ من الشمسِ والقمرِ والكواكبِ يسبح في فلكه ومداره بدقّةٍ لا تختلّ «وكل في فلك يسبحون»؛ فهذا الإحكامُ العجيبُ للنظامِ الكونيِّ آيةٌ على قدرةِ الله وحكمته وعلمه؛ فلا يقع في الكونِ خللٌ ولا اضطراب، بل كلُّ شيءٍ يجري بأمرِ الله وتقديره؛ فمن أحكم هذا النظامَ البديعَ يستحقّ أن يُعبَد وحده؛ فاعبد المدبّرَ الحكيمَ الذي أتقن كلَّ شيء؛ فمن تأمّل انتظامَ الكونِ ودقّةَ نظامه عرف عظمةَ خالقه؛ فاجعل نظرك في آياتِ الله الكونيةِ سبيلًا لتعظيمه وعبادته؛ فالكونُ المنتظمُ شاهدٌ على وحدانيةِ مدبّره وحكمته."}},{"n":41,"reflection":{"text":"«وآية لهم أنا حملنا ذريتهم في الفلك المشحون»، وعلامةٌ لهم على نعمتنا أنا حملنا ذريّتهم (أسلافهم مع نوح) في السفينةِ المملوءة؛ ففي هذا آيةُ نعمةِ الفلكِ والنجاة؛ فتأمّل نعمةَ الله في تسخيرِ الفلكِ لحملِ الناس، واشكره عليها، فمن سخّر لك السفنَ لتحملك يستحقّ شكرك، فالفلكُ نعمةٌ تستوجب الحمدَ والاعتبار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في نعمةِ الفلكِ والنجاة، وشكرُ الله عليها."},"action":{"text":"تأمّل آيةَ الله ونعمته في تسخيرِ الفلكِ (السفن) لحملِ الناسِ وأمتعتهم عبر البحار، فقد حمل الله أسلافهم (مع نوح) في السفينةِ المملوءةِ فنجّاهم «وآية لهم أنا حملنا ذريتهم في الفلك المشحون»؛ فاشكر الله على نعمةِ تسخيرِ الفلكِ والوسائلِ التي تحملك وتنقلك؛ فلولا تسخيرُ الله لما جرت السفنُ في البحرِ ولا حملتك؛ فاجعل هذه النعمةَ سبيلًا للشكرِ والاعتبار؛ فكلّما ركبت سفينةً أو وسيلةَ نقلٍ فتذكّر منعمها واشكره؛ فمن تأمّل نعمَ الله المسخّرةَ له وشكرها زاده الله؛ فاجعل النعمَ داعيةً للشكرِ لا للغفلة؛ فالله سخّر لك ما في الكونِ لتشكره وتعبده؛ فقابل نعمه بالحمدِ والطاعة."}},{"n":42,"reflection":{"text":"«وخلقنا لهم من مثله ما يركبون»، وخلقنا لهم من مثلِ الفلكِ ما يركبون (من الدوابِّ ووسائلِ النقل)؛ ففي هذا تعدادُ نعمِ الله في وسائلِ النقل؛ فتأمّل نعمَ الله في تسخيرِ وسائلِ النقلِ المتنوّعة، واشكره عليها، فمن سخّر لك ما تركبه في البرِّ والبحرِ يستحقّ شكرك، فالنعمُ المسخّرةُ تستوجب الشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في نعمِ وسائلِ النقلِ المسخّرة، وشكرُ الله عليها."},"action":{"text":"تأمّل نعمَ الله في تسخيرِ وسائلِ النقلِ المتنوّعةِ التي تركبها في البرِّ والبحرِ والجوّ، فقد خلق لك من مثلِ الفلكِ ما تركبه من الدوابِّ وغيرها «وخلقنا لهم من مثله ما يركبون»؛ فاشكر الله على هذه النعمِ التي تيسّر لك التنقّلَ وقضاءَ الحوائج؛ فكلُّ ما تركبه وتنتقل به فبتسخيرِ الله؛ فاجعل هذه النعمَ سبيلًا للشكرِ والاعتبار؛ فكلّما ركبت وسيلةَ نقلٍ فاذكر منعمها واشكره، وقل ما علّمك النبيُّ ﷺ من ذكرِ الركوب؛ فمن تأمّل نعمَ الله المسخّرةَ له وشكرها زاده الله؛ فالله سخّر لك ما في الكونِ من وسائلَ لتشكره وتعبده وتستعين بها على طاعته؛ فلا تستعمل نعمَ الله في معصيته؛ بل اجعلها عونًا لك على طاعته وشكره."},"qadiyya":{"title":"قضيّةُ الموضع الواحد: إمامٌ يكتب تفسير المصحف كلِّه فيقول عن آيةٍ إنّها أشكلت عليه","question":"المفسّرُ حين يجلس لتفسير كتاب الله **يُتوقَّع منه أن يفسّر**. **فماذا يصنع إذا بلغ موضعًا لم يستبِن له؟**\n**له أن يختار قولًا ويمضي، فلا يشعر القارئُ بشيء.** وله أن يسوق الأقوالَ بلا ترجيح، فيبدو أنّه جامعٌ لا محقّق.\n**والإمامُ السعديُّ صنع في آيةٍ من سورة يس شيئًا ثالثًا**: **كتب أنّها أشكلت عليه هو.**\nقال: «**وهذا الموضعُ من أشكل المواضع عليَّ في التفسير**».\nفالقضيّة: **ما الذي أشكل؟ وكيف تصرّف فيه؟ وما الذي نتعلّمه من رجلٍ يُدوّن عجزَه في كتابٍ يُقرأ بعده بقرون؟**","background":"ولا يُفهم موضعُ الإشكال حتى نقرأ الآيتين معًا من الصفر:\n**قال الله**: ﴿وآيةٌ لهم أنّا حملنا **ذرّيّتَهم** في الفلك المشحون، وخلقنا **لهم** من مثله ما يركبون﴾.\n**فالضميرُ في الأولى «ذرّيّتَهم»، وفي الثانية «لهم».**\n**وموضعُ الإشكال**: من المحمولون في الفلك؟ **إن كانوا الآباءَ (أي نوحًا ومن معه) فلمَ سُمّوا «ذرّيّة»؟** فالذرّيّةُ في القرآن هي النسلُ لا الأصول. **وإن كانوا الأبناءَ فما معنى ﴿وخلقنا لهم من مثله ما يركبون﴾؟** فيصير تكرارًا.\n**وهذا كلُّه إشكالٌ في مرجع الضمير، وهو من دقيق علم التفسير.**","what_happened":"**أمّا صنيعُه فكان على أربع خطوات، وكلُّها مسطورةٌ في كتابه:**\n**الأولى: أنّه ردّ قولَ الأكثرين وبيّن علّةَ ردّه.** فقد فسّر كثيرٌ من المفسّرين «الذرّيّة» بالآباء، **فردّه بأنّه** «**ممّا لا يُعهد في القرآن إطلاقُ الذرّيّة على الآباء، بل فيها من الإيهام، وإخراجِ الكلام عن موضوعه، ما يأباه كلامُ ربّ العالمين**».\n**فتأمّلْ ميزانه**: **عادةُ القرآن في استعمال اللفظ**، ثمّ **أنّ الحملَ عليه يُوقع في إيهام**، والقرآنُ أُنزل للبيان.\n**والثانية: أنّه عرض احتمالًا استحسنه هو** (أن يكون المرادُ بالذرّيّة الجنسَ، أي المخاطَبين أنفسَهم)، **ثمّ نقضه بنفسه**: «**ولكن ينقض هذا المعنى قولُه ﴿وخلقنا لهم من مثله ما يركبون﴾**»، لأنّه يصير تكرارًا، «**تأباه فصاحةُ القرآن**».\n**فردَّ قولَه هو كما ردّ قولَ غيره.**\n**والثالثة: أنّه لم يتكلّف حسمًا.** بل ختم بقوله: «**والله أعلم بحقيقة الحال**».\n**والرابعة، وهي التي لم يكن مضطرًّا إلى كتابتها**: أنّه قال بعد ذلك: «**فلمّا وصلتُ في الكتابة إلى هذا الموضع، ظهر لي معنًى ليس ببعيدٍ من مراد الله تعالى**»، ثمّ ذكره.\n**فحصل شيءٌ وهو يكتب، فأثبته. ولم يرجع فيمحو إقرارَه بالإشكال قبله.**\n**⭐ ووسمه بوسمه**: فلم يقل إنّ الصواب ظهر له، وإنّما قال إنّه «**معنًى ليس ببعيدٍ من مراد الله**». **فحدَّ قوّةَ قوله بلفظه.**","the_verdict":"**فالحاصلُ أربعةُ أشياءَ في صفحةٍ واحدة، وكلُّها منهجٌ لا حكاية:**\n**الأوّل: أن يُقال «لا أعلم» في موضعه.** **وليس هذا تقصيرًا**؛ فقد كتب الرجلُ تفسيرَ ستّة آلاف آية، **وقال هذا في موضعٍ واحد.** **فالوقوفُ إنّما يُعرف قدرُه بكثرة ما لم يقف عنده.**\n**والثاني: أنّ الإشكال المسطورَ أنفعُ من الحسم المتكلَّف.** **فإنّه لم يقل «أشكل عليّ» ثمّ يسكت**؛ **بل أرانا الاحتمالات وعلّةَ سقوط كلٍّ منها.** **فأعطى القارئَ أدواتِ النظر وإن لم يعطه الجواب.** **والذي يقول «لا أعلم» بلا بيانٍ يترك قارئَه حيث وجده؛ والذي يبيّن أين وقف يُقدّمه خطوات.**\n**والثالث: أنّه نقض قولَ نفسِه كما نقض قولَ غيره.** **وهذا أشقُّ**، لأنّ الاحتمال الذي يستحسنه المرءُ يميل إليه قلبُه. **ومن لم يعتد نقضَ ما يستحسنه لم يأمن أن يبني على استحسانه.**\n**والرابع، وهو أدقُّها: أنّه لم يمحُ سجلَّ حيرته حين زالت.** **وكان يستطيع.** **ولو محاه لخرج النصُّ أنظفَ وأقلَّ نفعًا.** **فإنّ الذي بقي في الكتاب ليس الجوابَ وحده، بل الطريقَ إليه؛ والطريقُ يُعلّم أكثرَ ممّا يُعلّم المنتهى.**\n**⭐ وأمّا وسمُه لما ظهر له بـ«ليس ببعيد» فهو تمامُ الأمانة.** فإنّ النفس إذا وجدت جوابًا بعد عناءٍ **مالت إلى تعظيمه**، لأنّها دفعت فيه ثمنًا. **فحدَّ الرجلُ قولَه بحدّه ولم يرفعه بقدر تعبه فيه.** **والذي يرفع قولَه لأنّه أتعبه، يقيس قوّةَ الدليل بمقدار ما بذل، وهما لا يتلازمان.**","for_you":"**فأمّا الذي تخرج به فثلاثة، وكلُّها في طريقة عملك لا في هذه الآية:**\n**الأوّل: إذا لم تعرف فقل، وبيّن أين وقفت.** **فليس المطلوبُ أن تقول «لا أدري» وتصمت، بل أن تقول: نظرتُ في كذا فسقط لكذا، وفي كذا فسقط لكذا، وبقي عندي كذا.** **فهذا الجهلُ المرتَّبُ أنفعُ من علمٍ مبعثَر.**\n**والثاني: انقضْ ما يعجبك من رأيك.** **فأشقُّ ما على المرء أن يهدم احتمالًا استحسنه هو.** **فإذا وجدتَ نفسَك تفتّش عن علل لردّ أقوال الناس ولا تفتّش عن علّةٍ لردّ قولك، فاعلم أنّك تنتصر لا تبحث.**\n**والثالث: لا تمحُ سجلّ ترددك حين تصل.** **فإذا كتبتَ شيئًا أو علّمتَه، وكنتَ قد ترددتَ فيه ثمّ ظهر لك، فاذكر الترددَ والظهورَ معًا.** **فالناسُ يتعلّمون من طريقك أكثر ممّا يتعلّمون من نتيجتك؛ ومن أراهم النتيجةَ وحدها أوهمهم أنّ الطريق قصير، فإذا سلكوه فتعثّروا ظنّوا أنّ الخللَ فيهم.**\n**وأمّا الرابعةُ فهي ميزانٌ لك عند كلِّ جوابٍ تصل إليه بعد تعب**: **حدَّ قولَك بحدّه، ولا ترفعه بمقدار ما بذلتَ فيه.**","grade":"ma'thur","source":"إقرارُ السعديّ («وهذا الموضع من أشكل المواضع علي في التفسير»)، وردُّه لقول الأكثرين («مما لا يعهد في القرآن إطلاق الذرية على الآباء، بل فيها من الإيهام، وإخراج الكلام عن موضوعه، ما يأباه كلام رب العالمين»)، ونقضُه للاحتمال الذي استحسنه («ولكن ينقض هذا المعنى قوله: ﴿وخلقنا لهم من مثله ما يركبون﴾»، «فيكون ذلك تكريرا للمعنى، تأباه فصاحة القرآن»)، ووقوفُه («والله أعلم بحقيقة الحال»)، وما ظهر له («فلما وصلت في الكتابة إلى هذا الموضع، ظهر لي معنى ليس ببعيد من مراد الله تعالى»): كلُّها بنصّها في تفسير السعديّ (٣٦:٤٢).","honesty":"وممّا يجب أن يُقال:\n**قولُنا إنّ هذا الموضعَ الوحيدُ الذي يُقرّ فيه السعديُّ بالإشكال على نفسه من عملنا نحن**: مُسح تفسيرُه للسور المئة والأربع عشرة، فلم نجد إقرارَه بالإشكال على نفسه إلّا ها هنا. **وقد وردت مادّة «أشكل» في موضعين آخرين، وهما في إشكال غيره لا إشكاله** (إشكالُ المتشابه على أهل الزيغ في آل عمران، وإشكالُ المسألة على المتعلّم في القيامة). **وهذا كلُّه اختبارٌ يُشغَّل، وهو في أدوات هذا المشروع لمن أراد أن يمسح بنفسه.**\n**وأمّا تقسيمُنا لصنيعه أربعَ خطواتٍ فمن ترتيبنا**، والألفاظُ كلُّها له.\n**ولم نرجّح في مرجع الضمير في الآية شيئًا**، وقد وقف الإمامُ عنه، **فليس لنا أن نحسم ما وقف عنده.**\n**وأمّا ما ظهر له فقد نقلناه بوسمه الذي وسمه به («ليس ببعيد»)، ولم نرفعه عن رتبته.**"}},{"n":43,"reflection":{"text":"«وإن نشأ نغرقهم فلا صريخ لهم ولا هم ينقذون»، وإن نشأ نغرق راكبي الفلكِ فلا مغيثَ يغيثهم ولا هم يُنقَذون؛ ففي هذا تقريرُ أنّ النجاةَ بيدِ الله، وأنّ نعمةَ السلامةِ منّةٌ منه؛ فاعلم أنّ نجاتك في كلِّ حالٍ بيدِ الله، فلولا حفظه لغرقت وهلكت، فاشكر نعمةَ السلامةِ والحفظ، والجأ إلى الله وحده في نجاتك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ أنّ النجاةَ بيدِ الله، وشكرُ نعمةِ السلامة."},"action":{"text":"اعلم أنّ نجاتك وسلامتك في كلِّ حالٍ بيدِ الله وحده، فلو شاء الله لأغرق راكبي الفلكِ فلا مغيثَ لهم ولا منقذ «وإن نشأ نغرقهم فلا صريخ لهم ولا هم ينقذون»؛ فلولا حفظُ الله لك لهلكت في كلِّ لحظة؛ فاشكر نعمةَ السلامةِ والحفظِ التي تعيشها؛ والجأ إلى الله وحده في طلبِ النجاةِ والحفظ؛ فلا تعتمد على قوّتك أو وسائلك، بل على حفظِ الله؛ فكم من أسبابٍ للهلاكِ صرفها الله عنك بحفظه؛ فاحمد الله على سلامتك في كلِّ يوم؛ ولا تنسَ أنّ حياتك وسلامتك منّةٌ من الله؛ فمن أيقن أنّ النجاةَ بيدِ الله التجأ إليه وشكره؛ فاجعل قلبك معلّقًا بحفظِ الله لا بالأسباب؛ فالحافظُ هو الله، والأسبابُ بيده؛ فاشكره على نعمةِ الحفظِ والسلامة، واطلبها منه دائمًا."}},{"n":44,"reflection":{"text":"«إلا رحمة منا ومتاعا إلى حين»: لكن ننجّيهم رحمةً منا ومتاعًا لهم إلى أجلٍ محدّد؛ ففي هذا أنّ النجاةَ والبقاءَ رحمةٌ من الله ومتاعٌ مؤقّت؛ فاعلم أنّ بقاءك ومتاعك في الدنيا رحمةٌ من الله ومتاعٌ إلى حين، فاغتنم هذا المتاعَ المؤقّتَ في طاعةِ الله، ولا تغترَّ به، فالحياةُ متاعٌ إلى أجل، فاعمل لما بعده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الرحيم"],"heart_state":{"text":"معرفةُ أنّ البقاءَ رحمةٌ ومتاعٌ مؤقّت، واغتنامُه في الطاعة."},"action":{"text":"اعلم أنّ نجاتك وبقاءك ومتاعك في الدنيا إنما هو رحمةٌ من الله ومتاعٌ مؤقّتٌ إلى أجلٍ محدّد «إلا رحمة منا ومتاعا إلى حين»؛ فبقاؤك في الدنيا وتمتّعك بنعمها منّةٌ من الله ورحمة، وهو متاعٌ زائلٌ إلى حين؛ فاغتنم هذا المتاعَ المؤقّتَ في طاعةِ الله والعملِ الصالح؛ ولا تغترَّ به فتظنّه دائمًا؛ فالحياةُ الدنيا متاعٌ إلى أجل، ثم الرحيلُ والحساب؛ فاعمل لما بعد هذا المتاع؛ فمن أيقن أنّ متاعَ الدنيا مؤقّتٌ رحمةً من الله، اغتنمه في الطاعةِ وشكر المنعم، ولم يركن إليه؛ فاشكر الله على رحمته وإمهاله ومتاعه؛ واجعل هذا المتاعَ المؤقّتَ زادًا لآخرتك الباقية؛ فالعاقلُ من استعمل متاعَ الدنيا الفاني في تحصيلِ النعيمِ الباقي؛ فاغتنم مهلةَ الحياةِ قبل انقضائها."}}]},{"title":"إعراضُ المكذّبين واستعجالُهم، والصيحةُ المباغتة","range":[45,50],"theme":"إعراضُ المكذّبين عن التقوى وعن الآيات، واحتجاجُهم بالقدرِ على تركِ الإنفاق، واستعجالُهم الوعدَ استهزاءً، والصيحةُ التي تأخذهم بغتةً وهم يخصمون فلا يستطيعون وصيّةً ولا رجوعًا","verses":[{"n":45,"reflection":{"text":"«وإذا قيل لهم اتقوا ما بين أيديكم وما خلفكم لعلكم ترحمون»، وإذا قيل للمعرضين: اتّقوا ما بين أيديكم من أمرِ الآخرة وما خلفكم من عذابِ الدنيا لعلّكم تُرحَمون، أعرضوا؛ ففي هذا الدعوةُ إلى التقوى رجاءَ الرحمة؛ فاتّقِ الله في أمرِ آخرتك ودنياك رجاءَ رحمته، فالتقوى سببُ الرحمة، فمن اتّقى الله رحمه، فبادر بالتقوى قبل فواتِ الأوان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التقوى في أمرِ الآخرةِ والدنيا رجاءَ رحمةِ الله."},"action":{"text":"اتّقِ الله في أمرِ آخرتك (ما بين يديك من أهوالِ القيامةِ وعذابها) وفي أمرِ دنياك (ما خلفك من عقوباتٍ عاجلة)، رجاءَ رحمةِ الله «اتقوا ما بين أيديكم وما خلفكم لعلكم ترحمون»؛ فالتقوى سببُ الرحمةِ في الدنيا والآخرة؛ فبادر بتقوى الله: بفعلِ أوامره واجتنابِ نواهيه؛ ولا تكن كالمعرضين الذين إذا دُعوا إلى التقوى أعرضوا؛ فمن اتّقى الله رحمه ووقاه العذاب؛ فاجعل التقوى زادك في كلِّ أمر؛ فبها تُنال رحمةُ الله والنجاةُ من عذابه؛ فراقب الله في أعمالك، واحذر ما يوجب سخطه؛ فالتقوى حصنٌ من العقوبات، وسببٌ للرحماتِ والبركات؛ فبادر بها قبل فواتِ الأوان؛ فمن اتّقى الله في حياته نال رحمته يومَ لقائه."}},{"n":46,"reflection":{"text":"«وما تأتيهم من آية من آيات ربهم إلا كانوا عنها معرضين»، وما تأتي المعرضين آيةٌ من آياتِ ربّهم إلا أعرضوا عنها ولم ينتفعوا بها؛ ففي هذا ذمُّ الإعراضِ عن آياتِ الله؛ فاحذر الإعراضَ عن آياتِ الله، فمن أعرض عنها حُرِم الانتفاعَ بها، فأقبل على آياتِ الله بالتدبّرِ والاعتبارِ والعمل، فالمعرضُ عن الآياتِ محرومٌ من هداها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإعراضِ عن آياتِ الله، والإقبالُ عليها."},"action":{"text":"احذر الإعراضَ عن آياتِ الله الكونيةِ والشرعية، فمن أعرض عنها حُرِم الانتفاعَ بها والاهتداءَ بهداها، كحالِ المعرضين الذين ما تأتيهم آيةٌ إلا أعرضوا عنها «وما تأتيهم من آية من آيات ربهم إلا كانوا عنها معرضين»؛ فأقبل على آياتِ الله بالتدبّرِ والاعتبارِ والعمل؛ فإذا بلغتك آيةٌ من القرآنِ فتدبّرها واعمل بها؛ وإذا رأيت آيةً في الكونِ فاعتبر بها وسبّح خالقها؛ فالآياتُ إنما أُنزِلت وخُلِقت للاعتبارِ والاهتداء؛ فلا تمرَّ عليها مرورَ الغافلين المعرضين؛ بل تفاعل معها بقلبٍ واعٍ؛ فمن أقبل على آياتِ الله انتفع بها واهتدى، ومن أعرض عنها حُرِم؛ فاجعل قلبك مقبلًا على آياتِ الله، متدبّرًا معتبرًا عاملًا؛ فالإعراضُ عن الآياتِ حرمانٌ، والإقبالُ عليها هدًى ونور."}},{"n":47,"reflection":{"text":"«وإذا قيل لهم أنفقوا مما رزقكم الله قال الذين كفروا للذين آمنوا أنطعم من لو يشاء الله أطعمه إن أنتم إلا في ضلال مبين»، وإذا قيل للكفار: أنفقوا ممّا رزقكم الله، قالوا للمؤمنين ساخرين: أنطعم من لو شاء الله أطعمه؟ ما أنتم إلا في ضلالٍ واضح؛ ففي هذا ذمُّ البخلِ والاحتجاجِ بالقدرِ على تركِ الإنفاق؛ فأنفق ممّا رزقك الله ولا تحتجَّ بالقدرِ على البخل، فالإنفاقُ عبادةٌ أمر الله بها، والاحتجاجُ بالقدرِ على تركِ الطاعةِ باطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإنفاقُ ممّا رزق الله، وترْكُ الاحتجاجِ بالقدرِ على البخل."},"action":{"text":"أنفق ممّا رزقك الله في وجوهِ الخيرِ والبرّ، ولا تبخل ولا تحتجَّ بالقدرِ على تركِ الإنفاق، كما فعل الكفارُ الذين قالوا ساخرين: أنطعم من لو شاء الله أطعمه؟ «أنطعم من لو يشاء الله أطعمه»؛ فهذا احتجاجٌ باطلٌ بالقدرِ على تركِ الطاعة؛ فالله أمرك بالإنفاقِ وابتلاك به، وجعل في المالِ حقًّا للفقراء؛ فلا تجعل مشيئةَ الله حجّةً لبخلك؛ فأنفق طاعةً لله وإحسانًا للخلق؛ فمن أنفق ممّا رزقه الله بارك الله له وأخلف عليه؛ فالإنفاقُ عبادةٌ وطهرةٌ وبركة، والبخلُ حرمانٌ وشحّ؛ فاحذر الاحتجاجَ بالقدرِ على تركِ الواجبات؛ فالقدرُ يُؤمَن به ولا يُحتجُّ به على المعصيةِ أو تركِ الطاعة؛ فبادر بالإنفاقِ والبذل؛ فما نقص مالٌ من صدقة."}},{"n":48,"reflection":{"text":"«ويقولون متى هذا الوعد إن كنتم صادقين»، ويقول المكذّبون: متى يقع هذا الوعدُ بالبعثِ إن كنتم صادقين؟ ففي هذا استعجالهم استهزاءً وتكذيبًا؛ فلا يستفزّنك استعجالُ المستهزئين للوعد، فوقتُه بيدِ الله، والاستعجالُ به حمقٌ وجهلٌ بحكمةِ التأجيل، فوعدُ الله واقعٌ في وقته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاكتراثِ باستعجالِ المستهزئين للوعد."},"action":{"text":"لا يستفزّنك استعجالُ المكذّبين للوعدِ بالبعثِ والعذابِ على وجهِ الاستهزاءِ والتكذيب «ويقولون متى هذا الوعد إن كنتم صادقين»؛ فوقتُ وقوعه بيدِ الله وحده بحكمته؛ فلا تتعجّل أنت، ولا تضطرب لتعجّلهم؛ بل امضِ في الحقِّ صابرًا، وكِل الأمرَ إلى الله؛ فالمستعجلُ بالوعدِ جاهلٌ بأنّ في تأخيره حكمةً وإمهالًا؛ فاثبت على يقينك بوعدِ الله؛ فما هو آتٍ قريبٌ وإن استبطأه المستهزئون؛ فالعاقبةُ للصادقين، والخزيُ للمستهزئين؛ فلا تجعل استعجالهم يزعزع ثقتك بوعدِ الله؛ بل ازدد يقينًا وثباتًا؛ فوعدُ الله بالبعثِ حقٌّ لا يتخلّف، يقع في وقته المقدّر؛ فاستعدَّ له بالعملِ الصالح، ولا تكن كالمستعجلين المستهزئين الغافلين."}},{"n":49,"reflection":{"text":"«ما ينظرون إلا صيحة واحدة تأخذهم وهم يخصمون»: ما ينتظر هؤلاء المكذّبون إلا صيحةً واحدةً (النفخةَ الأولى) تأخذهم فجأةً وهم مشغولون بخصوماتهم ومعاملاتِ دنياهم؛ ففي هذا مباغتةُ الساعةِ للغافلين؛ فاستعدَّ للساعةِ التي تأتي بغتةً، فلا تنشغل بالدنيا عن الاستعداد للآخرة، فالساعةُ تأخذ الناسَ وهم غافلون مشغولون، فكن مستعدًّا دائمًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للساعةِ التي تأتي بغتةً حالَ الغفلة."},"action":{"text":"استعدَّ للساعةِ التي تأتي بغتةً، فما ينتظر المكذّبون إلا صيحةً واحدةً (النفخةَ الأولى) تأخذهم فجأةً وهم مشغولون بخصوماتهم ومعاملاتِ دنياهم غافلون «ما ينظرون إلا صيحة واحدة تأخذهم وهم يخصمون»؛ فلا تنشغل بالدنيا وملذّاتها وخصوماتها عن الاستعدادِ للآخرة؛ فالساعةُ تأخذ الناسَ وهم في غفلتهم وأشغالهم؛ فكن مستعدًّا دائمًا بالإيمانِ والعملِ الصالحِ والتوبة؛ فلا تدري متى تأتيك ساعتك (موتُك) أو الساعةُ الكبرى؛ فمن عاش مستعدًّا لم تفجأه على غفلة؛ فبادر بالتوبةِ والعملِ من الآن؛ ولا تسوّف؛ فالأجلُ يأتي بغتةً حين لا يُحتسَب؛ فاجعل قلبك متأهّبًا للقاءِ الله في كلِّ لحظة؛ فالكيّسُ من استعدّ للرحيلِ قبل أن يُباغَت به."}},{"n":50,"reflection":{"text":"«فلا يستطيعون توصية ولا إلى أهلهم يرجعون»: فلا يستطيعون حينئذٍ أن يوصوا وصيّةً ولا أن يرجعوا إلى أهلهم من سرعةِ أخذِ الصيحةِ لهم؛ ففي هذا سرعةُ مباغتةِ الساعةِ حتى لا مهلةَ للوصية؛ فبادر بالوصيةِ والعملِ الصالحِ قبل أن تأتيك الساعةُ فجأةً، فلا مهلةَ حينئذٍ لوصيةٍ ولا رجوع، فاستعدَّ قبل أن يُباغتك الأجل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالوصيةِ والعملِ قبل مباغتةِ الأجل."},"action":{"text":"بادر بالوصيةِ والتوبةِ والعملِ الصالحِ قبل أن تأتيك الساعةُ أو المنيّةُ فجأةً، فإنّ الصيحةَ تأخذ الناسَ بغتةً فلا يستطيعون حينئذٍ أن يوصوا وصيّةً ولا أن يرجعوا إلى أهلهم «فلا يستطيعون توصية ولا إلى أهلهم يرجعون»؛ فلا مهلةَ حينئذٍ لإصلاحِ ما فسد أو استدراكِ ما فات؛ فأصلح أمرك مع الله ومع الناسِ من الآن؛ وأوصِ بما يلزم، وردَّ المظالمَ إلى أهلها، وتُب من ذنوبك؛ فالأجلُ يأتي بغتةً حين لا تحتسب؛ فمن استعدَّ قبل مباغتةِ الأجلِ نجا، ومن سوّف حتى فاجأه الأجلُ ندم؛ فاغتنم مهلةَ الحياةِ في الاستعدادِ للقاءِ الله؛ فلا تؤجّل التوبةَ ولا العملَ ولا الوصية؛ فالموتُ يأتي بغتةً فلا يمهل؛ فبادر بالخيراتِ قبل فواتِ الأوان."}}]},{"title":"النفخُ في الصورِ والبعث، وعدلُ الجزاء، ونعيمُ أهلِ الجنّة","range":[51,58],"theme":"النفخُ في الصورِ وخروجُ الناسِ من القبور، واعترافُ المكذّبين بصدقِ الوعد، وعدلُ الجزاءِ يومَ القيامة، ونعيمُ أهلِ الجنّةِ وأزواجهم في الظلالِ والفاكهةِ وما يشتهون، وأعظمُه سلامُ الله عليهم","verses":[{"n":51,"reflection":{"text":"«ونفخ في الصور فإذا هم من الأجداث إلى ربهم ينسلون»، ونُفِخ في الصورِ (النفخةُ الثانية) فإذا هم من القبورِ إلى ربّهم يسرعون للحساب؛ ففي هذا تقريرُ البعثِ من القبور؛ فأيقن بالبعثِ من القبور، فإذا نُفِخ في الصورِ خرج الناسُ من قبورهم مسرعين إلى ربّهم، فاستعدَّ لذلك اليومِ العظيمِ بالعملِ الصالح.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ من القبورِ والاستعدادُ له."},"action":{"text":"أيقن بالبعثِ من القبور، فإذا نُفِخ في الصورِ النفخةُ الثانيةُ خرج الناسُ من قبورهم أحياءً مسرعين إلى ربّهم للحساب «ونفخ في الصور فإذا هم من الأجداث إلى ربهم ينسلون»؛ فاستعدَّ لذلك اليومِ العظيمِ بالإيمانِ والعملِ الصالحِ والتوبة؛ فاستحضر مشهدَ خروجك من قبرك مسرعًا إلى الله؛ فيحملك ذلك على المبادرةِ بالعملِ الصالح؛ فمن أيقن بالبعثِ عمل له، ومن غفل عنه فرّط؛ فاجعل هذا اليقينَ حاديًا لك إلى الطاعةِ وزاجرًا عن المعصية؛ فأنت راحلٌ عن الدنيا إلى القبر، ثم مبعوثٌ منه إلى ربّك؛ فقدّم لذلك اليومِ ما ينفعك؛ فالبعثُ حقٌّ، والحسابُ آتٍ؛ فبادر بالزادِ قبل الرحيل."}},{"n":52,"reflection":{"text":"«قالوا يا ويلنا من بعثنا من مرقدنا هذا ما وعد الرحمن وصدق المرسلون»: قال المكذّبون حين بُعِثوا: يا هلاكنا من بعثنا من نومنا (القبر)؟ ثم يُقال أو يقولون: هذا ما وعد الرحمنُ وصدق المرسلون؛ ففي هذا اعترافُ المكذّبين بصدقِ الوعدِ حين لا ينفع؛ فبادر بتصديقِ وعدِ الله والرسلِ في الدنيا، قبل أن تعترف به يومَ البعثِ حين لا ينفع الاعتراف، فصدّق بالبعثِ الآن، والرسلُ صادقون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الرحمن"],"heart_state":{"text":"تصديقُ وعدِ الله والرسلِ في الدنيا قبل الاعترافِ يومَ البعث."},"action":{"text":"بادر بتصديقِ وعدِ الله بالبعثِ وتصديقِ الرسلِ فيما أخبروا به في الدنيا، قبل أن تعترف بذلك يومَ البعثِ حين لا ينفع الاعتراف، كما يقول المكذّبون حين يُبعَثون: «يا ويلنا من بعثنا من مرقدنا هذا ما وعد الرحمن وصدق المرسلون»؛ فهم يعترفون بصدقِ وعدِ الله وصدقِ الرسلِ يومَ القيامةِ حيث لا ينفعهم الاعتراف؛ فلا تكن مثلهم؛ بل صدّق بالبعثِ والرسلِ من الآن، واعمل بمقتضى ذلك؛ فمن صدّق في الدنيا نفعه تصديقه، ومن أخّره إلى الآخرةِ لم ينفعه؛ فالرسلُ صادقون فيما أخبروا، ووعدُ الله حقٌّ لا محالة؛ فاجعل تصديقك بالغيبِ والبعثِ راسخًا، واعمل ليومِ اللقاء؛ فالسعيدُ من صدّق وعمل قبل أن يُعايِن."}},{"n":53,"reflection":{"text":"«إن كانت إلا صيحة واحدة فإذا هم جميع لدينا محضرون»: ما كانت إلا صيحةً واحدةً (النفخةُ الثانية) فإذا الخلقُ جميعًا محضَرون بين يدي الله للحساب؛ ففي هذا سرعةُ البعثِ وحشرُ الخلقِ جميعًا؛ فاستعدَّ ليومِ يُحضَر فيه الخلقُ جميعًا للحساب، فبصيحةٍ واحدةٍ يُبعَث الجميعُ ويُحضَرون، فاعمل لذلك اليومِ الذي لا مفرَّ منه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومِ يُحضَر فيه الخلقُ جميعًا للحساب."},"action":{"text":"استعدَّ ليومِ الحشرِ العظيم، الذي بصيحةٍ واحدةٍ يُبعَث فيه الخلقُ كلُّهم فيُحضَرون جميعًا بين يدي الله للحساب «إن كانت إلا صيحة واحدة فإذا هم جميع لدينا محضرون»؛ فما أيسرَ البعثَ على الله: صيحةٌ واحدةٌ يُحشَر بها الخلقُ أجمعون؛ فاعمل لذلك اليومِ الذي لا مفرَّ منه؛ فكلُّ نفسٍ ستُحضَر للحساب؛ فبادر بالتوبةِ والعملِ الصالحِ قبل ذلك اليوم؛ فاستحضر أنك واقفٌ بين يدي الله مع الخلائقِ كلِّهم؛ فيحملك ذلك على المراقبةِ والاستعداد؛ فمن أيقن بالحشرِ والحسابِ عمل له؛ فاجعل استحضارَ يومِ الحشرِ حاديًا لك إلى الطاعةِ وزاجرًا عن المعصية؛ فالبعثُ يسيرٌ على الله، والحسابُ آتٍ لا محالة؛ فاستعدَّ له بالإيمانِ والعملِ."}},{"n":54,"reflection":{"text":"«فاليوم لا تظلم نفس شيئا ولا تجزون إلا ما كنتم تعملون»: فاليومَ (يومَ القيامة) لا تُظلَم نفسٌ شيئًا من نقصِ حسنةٍ أو زيادةِ سيّئة، ولا تُجزَون إلا بأعمالكم؛ ففي هذا تقريرُ عدلِ الله في الجزاء؛ فاطمئنَّ إلى عدلِ الله يومَ القيامة، فلا يُظلَم أحدٌ شيئًا، والجزاءُ بالعمل، فقدّم لنفسك عملًا صالحًا، فما تجزى إلا بما عملت.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الطمأنينةُ إلى عدلِ الله، وتقديمُ العملِ الصالح."},"action":{"text":"اطمئنَّ إلى كمالِ عدلِ الله يومَ القيامة، فلا تُظلَم نفسٌ شيئًا: لا يُنقَص من حسناتها ولا يُزاد في سيّئاتها، ولا يُجزى أحدٌ إلا بما عمل «فاليوم لا تظلم نفس شيئا ولا تجزون إلا ما كنتم تعملون»؛ فالجزاءُ بالعملِ بالعدلِ التام؛ فقدّم لنفسك عملًا صالحًا يوفّيك الله جزاءه؛ فما تجزى إلا بما عملت؛ فاحرص على الإكثارِ من الحسنات، واجتنابِ السيّئات؛ فكلُّ عملٍ محفوظٌ مجزيٌّ عليه بالعدل؛ فمن عمل خيرًا وجده، ومن عمل شرًّا لقيه؛ فلا تظلم نفسك بالتفريطِ في العملِ الصالحِ أو بارتكابِ السيّئات؛ فالله عدلٌ لا يظلم أحدًا؛ فاجعل عملك خالصًا صالحًا؛ فبه تُجزى خيرًا يومَ لا ينفع إلا العمل؛ فاعمل لآخرتك عملَ من يوقن بعدلِ الله وجزائه."}},{"n":55,"reflection":{"text":"«إن أصحاب الجنة اليوم في شغل فاكهون»: إنّ أصحابَ الجنّةِ اليومَ في شغلٍ يشغلهم عن غيرهم من التنعّم واللذّة، فرحين متلذّذين؛ ففي هذا وصفُ نعيمِ أهلِ الجنّة؛ فاعمل لتكون من أصحابِ الجنّةِ المتنعّمين، فنعيمُ الجنّةِ يشغل أهلها عن كلِّ همّ، فاجتهد لتنال هذا النعيمَ الذي لا ينقطع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لتكون من أصحابِ الجنّةِ المتنعّمين."},"action":{"text":"اعمل الصالحاتِ لتكون من أصحابِ الجنّةِ الذين هم في شغلٍ من النعيمِ واللذّةِ يشغلهم عن كلِّ همّ، فرحين متلذّذين بما هم فيه «إن أصحاب الجنة اليوم في شغل فاكهون»؛ فنعيمُ الجنّةِ يشغل أهلها عن كلِّ ما سواه من الأحزانِ والهموم؛ فاجتهد لتنال هذا النعيمَ الدائمَ الذي لا ينقطع؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله، طامعًا في نعيمِ الجنّة؛ فمن عمل للجنّةِ عملَ أهلها نالها؛ فالجنّةُ سلعةُ الله الغالية، ثمنُها الإيمانُ والعملُ الصالح؛ فاعمل لها عملَ من يرجو دخولها ونعيمها؛ فبعد تعبِ الدنيا وهمومها راحةٌ ونعيمٌ دائمٌ في الجنّة؛ فاصبر على تعبِ الطاعةِ رجاءَ نعيمِ الجنّة؛ فالنعيمُ الدائمُ يستحقّ كلَّ جهد."}},{"n":56,"reflection":{"text":"«هم وأزواجهم في ظلال على الأرائك متكئون»: هم وأزواجهم في ظلالٍ وارفةٍ على الأسرّةِ المزيّنةِ متّكئون في راحةٍ ونعيم؛ ففي هذا وصفُ راحةِ أهلِ الجنّةِ ونعيمهم؛ فاعمل لتنال هذه الراحةَ والنعيمَ مع أزواجك في الجنّة، فنعيمُ الجنّةِ راحةٌ دائمةٌ ومتعةٌ لا تنقطع، فاجتهد لتكون من أهله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ راحةِ الجنّةِ ونعيمها مع الأزواج."},"action":{"text":"اعمل الصالحاتِ لتنال راحةَ الجنّةِ ونعيمها، حيث يكون المؤمنون وأزواجهم في ظلالٍ وارفةٍ على الأسرّةِ المزيّنةِ متّكئين في راحةٍ ونعيمٍ دائم «هم وأزواجهم في ظلال على الأرائك متكئون»؛ فنعيمُ الجنّةِ راحةٌ دائمةٌ ومتعةٌ لا تنقطع، يجتمع فيها المؤمنُ بأهله المؤمنين؛ فاجتهد لتكون من أهلها؛ واحرص على أن يكون أهلك معك من أهلِ الجنّةِ بتربيتهم على الإيمانِ والطاعة؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله؛ فمن عمل للجنّةِ نالها هو وأهله المؤمنون؛ فالجنّةُ دارُ الراحةِ والنعيمِ والاجتماعِ بالأحبّة؛ فاعمل لها، وأعِن أهلك على العملِ لها؛ فبعد فراقِ الدنيا اجتماعٌ في الجنّةِ ونعيمٌ دائم؛ فاجعل غايتك وغايةَ أهلك الجنّةَ ونعيمها."}},{"n":57,"reflection":{"text":"«لهم فيها فاكهة ولهم ما يدعون»: لهم في الجنّةِ فاكهةٌ لذيذة، ولهم كلُّ ما يطلبون ويشتهون؛ ففي هذا سعةُ نعيمِ الجنّةِ وتحقّقُ كلِّ مطلوب؛ فاعمل لتنال جنّةً فيها كلُّ ما تشتهي، فنعيمُ الجنّةِ يحقّق كلَّ رغبة، فاجتهد لتكون من أهلها، طامعًا في نعيمٍ لا حدَّ له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ جنّةٍ فيها كلُّ ما تشتهي النفس."},"action":{"text":"اعمل الصالحاتِ لتنال جنّةً فيها فاكهةٌ لذيذةٌ متنوّعة، ولك فيها كلُّ ما تطلب وتشتهي «لهم فيها فاكهة ولهم ما يدعون»؛ فنعيمُ الجنّةِ يحقّق كلَّ رغبةٍ وأمنية، ولا يُمنَع أهلها شيئًا يطلبونه؛ فاجتهد لتكون من أهلها، طامعًا في نعيمٍ لا حدَّ له ولا انقطاع؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله؛ فمن عمل للجنّةِ نال فيها كلَّ ما تشتهيه نفسه وتلذّ عينه؛ فالجنّةُ فيها ما لا عينٌ رأت ولا أذنٌ سمعت ولا خطر على قلبِ بشر؛ فاعمل لها عملَ من يرجو نعيمها؛ فكلُّ ما حُرِمته في الدنيا من لذّةٍ مباحةٍ ستجده في الجنّةِ إن كنت من أهلها؛ فاصبر على حرمانِ الدنيا رجاءَ نعيمِ الجنّةِ الذي يحقّق كلَّ رغبة؛ فالنعيمُ الدائمُ يستحقّ الصبرَ والعمل."}},{"n":58,"reflection":{"text":"«سلام قولا من رب رحيم»: يُقال لهم سلامٌ، تحيّةً وقولًا من ربٍّ رحيمٍ بهم؛ ففي هذا أعظمُ نعيمِ الجنّةِ: سلامُ الله على أهلها؛ فاعمل لتنال سلامَ الله وتحيّته في الجنّة، فأعظمُ نعيمِ الجنّةِ سلامُ الرحمنِ على أهلها ورضاه عنهم، فاجتهد لتنال هذا الشرفَ العظيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الرحيم"],"heart_state":{"text":"العملُ لنيلِ سلامِ الله وتحيّته، أعظمِ نعيمِ الجنّة."},"action":{"text":"اعمل الصالحاتِ لتنال أعظمَ نعيمِ الجنّة: سلامَ الله وتحيّته على أهلها، قولًا منه سبحانه رحمةً بهم «سلام قولا من رب رحيم»؛ فأعظمُ نعيمِ الجنّةِ ليس الطعامَ والشرابَ واللذّاتِ فحسب، بل سلامُ الرحمنِ على أهلها ورضاه عنهم وكلامُه لهم؛ فذلك شرفٌ عظيمٌ يفوق كلَّ نعيم؛ فاجتهد لتنال هذا الشرفَ برضا الله عنك؛ فبادر بالأعمالِ الصالحةِ الخالصةِ لوجهِ الله؛ فمن رضي الله عنه سلّم عليه في الجنّة؛ فاجعل غايتك رضا الله وسلامه وكلامه؛ فذلك أعظمُ من كلِّ نعيمٍ حسّيّ؛ فالنظرُ إلى وجهِ الله وسماعُ سلامه أعلى لذّاتِ الجنّة؛ فاعمل لتكون من أهلِ هذا الشرف؛ فالرحيمُ يسلّم على أوليائه ويرضى عنهم؛ فاطلب رضاه بالإيمانِ والعملِ والإخلاص."}}]},{"title":"تمييزُ المجرمين، والعهدُ بعبادةِ الله، وشهادةُ الجوارح","range":[59,68],"theme":"تمييزُ المجرمين يومَ القيامة، وتذكيرُهم بالعهدِ بترْكِ طاعةِ الشيطانِ العدوِّ وعبادةِ الله وحده، وشهادةُ الجوارحِ عليهم، وقدرةُ الله على طمسِ الأبصارِ والمسخِ وتنكيسِ الخلق","verses":[{"n":59,"reflection":{"text":"«وامتازوا اليوم أيها المجرمون»، ويُقال للمجرمين يومَ القيامة: تميّزوا وانفصلوا اليومَ عن المؤمنين أيها المجرمون؛ ففي هذا تمييزُ المجرمين عن المؤمنين يومَ القيامة؛ فاحذر أن تكون من المجرمين المميَّزين عن المؤمنين يومَ القيامة، فاعمل صالحًا لتكون مع المؤمنين لا مع المجرمين، فيومَ القيامةِ يتميّز أهلُ الحقِّ عن أهلِ الباطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن تكون من المجرمين المميَّزين يومَ القيامة."},"action":{"text":"احذر أن تكون من المجرمين الذين يُقال لهم يومَ القيامة: امتازوا وانفصلوا عن المؤمنين «وامتازوا اليوم أيها المجرمون»؛ فيومَ القيامةِ يتميّز أهلُ الحقِّ عن أهلِ الباطل، وأهلُ الجنّةِ عن أهلِ النار؛ فاعمل الصالحاتِ لتكون مع المؤمنين لا مع المجرمين؛ فاختر لنفسك من الآن في أيِّ الفريقين تكون بعملك؛ فبادر بالإيمانِ والطاعةِ والتوبةِ لتُحشَر مع المؤمنين المكرَمين؛ واحذر الإجرامَ والمعاصيَ التي تجعلك من المميَّزين المطرودين؛ فراجع نفسك: أمع المؤمنين أنت أم مع المجرمين؟ فاجتهد أن تكون في زمرةِ المؤمنين؛ فيومَ الفصلِ لا رجعةَ ولا استدراك؛ فقدّم اليومَ ما يجعلك من أهلِ الكرامةِ لا من أهلِ الإهانة؛ فالسعيدُ من حُشِر مع المؤمنين، والشقيُّ من مُيِّز مع المجرمين."}},{"n":60,"reflection":{"text":"«ألم أعهد إليكم يا بني آدم أن لا تعبدوا الشيطان إنه لكم عدو مبين»: ألم آمركم وأوصكم يا بني آدمَ ألّا تطيعوا الشيطانَ (فطاعتُه عبادتُه)؟ إنه لكم عدوٌّ واضحُ العداوة؛ ففي هذا تذكيرٌ بالعهدِ بترْكِ طاعةِ الشيطان؛ فاذكر عهدَ الله إليك بترْكِ طاعةِ الشيطان، فطاعتُه عبادةٌ له، وهو عدوّك المبين، فلا تطعه فيما يأمرك به، فمن أطاعه فقد عبده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الوفاءُ بالعهدِ بترْكِ طاعةِ الشيطانِ العدوِّ المبين."},"action":{"text":"اذكر عهدَ الله إليك يا ابنَ آدمَ ألّا تطيع الشيطانَ، فإنّ طاعتَه فيما يأمر به من الكفرِ والمعصيةِ عبادةٌ له، وهو لك عدوٌّ واضحُ العداوة «ألم أعهد إليكم يا بني آدم أن لا تعبدوا الشيطان إنه لكم عدو مبين»؛ فأوفِ بهذا العهد: لا تطع الشيطانَ في وسوسته وإغوائه؛ فمن أطاعه فيما يزيّنه من الشرِّ فقد عبده من حيث لا يشعر؛ فعادِ الشيطانَ واحذره، وخالفه في كلِّ ما يأمرك به؛ واستعذ بالله منه دائمًا؛ فمن عادى الشيطانَ وترك طاعته نجا، ومن أطاعه هلك؛ فراقب نفسك: أتطيع الله أم تطيع الشيطان؟ فاجعل طاعتك لله وحده، ومخالفتك للشيطانِ في كلِّ أمر؛ فالوفاءُ بعهدِ الله بترْكِ طاعةِ الشيطانِ من تمامِ العبودية؛ فالشيطانُ عدوٌّ لا يريد إلا هلاكك؛ فلا تجعله متبوعًا مطاعًا."}},{"n":61,"reflection":{"text":"«وأن اعبدوني هذا صراط مستقيم»، وأن اعبدوني وحدي، هذا هو الصراطُ المستقيمُ الموصلُ إليّ؛ ففي هذا أنّ عبادةَ الله وحده هي الصراطُ المستقيم؛ فاعبد الله وحده، فذلك هو الصراطُ المستقيمُ الموصلُ إلى الله، فمن عبد الله وحده فهو على الصراطِ المستقيم، ومن أطاع الشيطانَ انحرف عنه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عبادةُ الله وحده هي الصراطُ المستقيم."},"action":{"text":"اعبد الله وحده ولا تشرك به شيئًا، فإنّ عبادتَه وحده هي الصراطُ المستقيمُ الموصلُ إليه «وأن اعبدوني هذا صراط مستقيم»؛ فالتوحيدُ وإخلاصُ العبادةِ لله هو الطريقُ المستقيمُ الذي أمر الله بسلوكه؛ فمن عبد الله وحده وأطاعه فهو على الصراطِ المستقيم، ومن أطاع الشيطانَ وعصى الله انحرف عنه؛ فاجعل عبادتك كلَّها لله: دعاءك وخوفك ورجاءك وتوكّلك؛ ولا تصرف شيئًا منها لغيره؛ فالعبادةُ الخالصةُ لله هي الغايةُ من الخلق، وهي الصراطُ المستقيم؛ فالزمها واثبت عليها؛ فمن سلك صراطَ عبادةِ الله وحده وصل إليه وإلى جنّته؛ ومن انحرف عنه بطاعةِ الشيطانِ والشركِ تاه وهلك؛ فاسأل الله الثباتَ على صراطِ التوحيدِ والعبادة؛ فهو الطريقُ الوحيدُ الموصلُ إلى رضا الله وجنّته."}},{"n":62,"reflection":{"text":"«ولقد أضل منكم جبلا كثيرا أفلم تكونوا تعقلون»، ولقد أضلَّ الشيطانُ منكم خلقًا كثيرًا، أفلم تكونوا تعقلون عداوته فتحذروه؟ ففي هذا التوبيخُ على اتّباعِ الشيطانِ مع وضوحِ عداوته؛ فاعقل عداوةَ الشيطانِ واحذره، فقد أضلَّ خلقًا كثيرًا، فلا تكن ممّن أضلّهم، بل استعمل عقلك في الحذرِ من عدوّك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استعمالُ العقلِ في الحذرِ من الشيطانِ الذي أضلّ كثيرًا."},"action":{"text":"استعمل عقلك في معرفةِ عداوةِ الشيطانِ والحذرِ منه، فقد أضلَّ منكم خلقًا كثيرًا وأهلكهم «ولقد أضل منكم جبلا كثيرا أفلم تكونوا تعقلون»؛ فكيف تتّبع عدوًّا أهلك من قبلك خلقًا كثيرًا؟ فذلك منافٍ للعقل؛ فاعقل عداوةَ الشيطانِ لك، واحذره أشدَّ الحذر؛ ولا تكن ممّن أضلّهم بطاعته واتّباعِ وسوسته؛ فمن استعمل عقله عرف أنّ الشيطانَ عدوٌّ لا يريد إلا هلاكه، فحذره وخالفه؛ ومن عطّل عقله اتّبع الشيطانَ فهلك؛ فاجعل عقلك حاكمًا يحذّرك من عدوّك؛ واستعذ بالله من الشيطانِ الرجيم؛ فالعاقلُ من حذر عدوَّه، والأحمقُ من أطاعه؛ فلا تكن ممّن أضلّهم الشيطانُ بتعطيلِ عقولهم واتّباعِ أهوائهم؛ بل كن عاقلًا حذرًا، مطيعًا لله، عاصيًا للشيطان."}},{"n":63,"reflection":{"text":"«هذه جهنم التي كنتم توعدون»: يُقال للمجرمين: هذه جهنمُ التي كنتم توعَدون بها في الدنيا فكذّبتم؛ ففي هذا تحقّقُ الوعيدِ للمكذّبين؛ فصدّق بوعيدِ الله في الدنيا قبل أن تراه، فجهنمُ التي يُكذَّب بها حقٌّ، فمن كذّب بها رآها، فاحذرها بالإيمانِ والعمل، ولا تكذّب بوعيدِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التصديقُ بوعيدِ الله والحذرُ من جهنمَ بالإيمانِ والعمل."},"action":{"text":"صدّق بوعيدِ الله في الدنيا قبل أن تعاينه، فجهنمُ التي يُكذَّب بها في الدنيا حقٌّ سيراها المكذّبون، ويُقال لهم: «هذه جهنم التي كنتم توعدون»؛ فمن كذّب بها رآها وذاق عذابها؛ فاحذر جهنمَ بالإيمانِ الصادقِ والعملِ الصالحِ والتوبةِ من المعاصي؛ ولا تكذّب بوعيدِ الله ولا تستهزئ به؛ فالوعيدُ حقٌّ واقعٌ لا محالة؛ فبادر بأسبابِ النجاةِ من النار: من التوحيدِ والطاعةِ والبعدِ عن المعاصي؛ فمن صدّق بوعيدِ الله واتّقى النارَ نجا منها، ومن كذّب بها ووقع في أسبابها دخلها؛ فاجعل خوفك من النارِ حاديًا لك إلى الطاعة، وزاجرًا عن المعصية؛ فالنارُ حقٌّ، وعذابها شديد؛ فاستعذ بالله منها، واعمل لتنجو منها؛ فالسعيدُ من صدّق بالوعيدِ فاتّقاه، والشقيُّ من كذّب به فوقع فيه."}},{"n":64,"reflection":{"text":"«اصلوها اليوم بما كنتم تكفرون»: يُقال لهم: ادخلوها وذوقوا حرّها اليومَ جزاءً بما كنتم تكفرون؛ ففي هذا أنّ دخولَ النارِ جزاءُ الكفر؛ فاحذر الكفرَ فجزاؤه صلي النار، فآمن بالله واعمل صالحًا لتنجو من هذا المصير، فالكفرُ سببُ دخولِ النار، والإيمانُ والعملُ سببُ النجاة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكفرِ الذي جزاؤه صلي النار."},"action":{"text":"احذر الكفرَ والجحودَ، فإنّ جزاءه صليَ النارِ وذوقَ عذابها، كما يُقال للكافرين: «اصلوها اليوم بما كنتم تكفرون»؛ فدخولُ النارِ جزاءٌ عادلٌ للكفرِ والتكذيب؛ فآمن بالله إيمانًا صادقًا، واعمل الصالحاتِ، لتنجو من هذا المصيرِ الأليم؛ فالكفرُ سببُ دخولِ النار، والإيمانُ والعملُ الصالحُ سببُ النجاةِ منها ودخولِ الجنّة؛ فاثبت على إيمانك، واحذر ما يناقضه من الشركِ والجحودِ والاستكبار؛ واشكر الله على نعمةِ الإيمانِ التي هداك إليها؛ فكم من كافرٍ مصيرُه النار، وأنت في نعمةِ الإيمان؛ فاحمد الله على هدايتك، وثبّت قدمك على الحقّ؛ فمن آمن وعمل صالحًا نجا من صلي النار، ومن كفر وأصرَّ صلاها؛ فاجعل همّك الثباتَ على الإيمانِ والعملِ حتى تلقى الله."}},{"n":65,"reflection":{"text":"«اليوم نختم على أفواههم وتكلمنا أيديهم وتشهد أرجلهم بما كانوا يكسبون»: اليومَ نختم على أفواهِ المجرمين فلا ينطقون، وتكلّمنا أيديهم وتشهد أرجلهم بما كانوا يكسبون من المعاصي؛ ففي هذا شهادةُ الجوارحِ على أصحابها يومَ القيامة؛ فاحذر أن تشهد عليك جوارحك يومَ القيامة، فاستعمل جوارحك في طاعةِ الله لا في معصيته، فيومَ القيامةِ تنطق الجوارحُ بما عملت، فأحسن استعمالها اليوم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من شهادةِ الجوارح، واستعمالُها في الطاعة."},"action":{"text":"احذر أن تشهد عليك جوارحك يومَ القيامةِ بما عملت من المعاصي، فإنّ الله يختم على أفواهِ المجرمين فلا ينطقون، وتنطق أيديهم وأرجلهم شاهدةً عليهم بما كسبوا «اليوم نختم على أفواههم وتكلمنا أيديهم وتشهد أرجلهم بما كانوا يكسبون»؛ فاستعمل جوارحك (يديك ورجليك وعينيك وأذنيك ولسانك) في طاعةِ الله لا في معصيته؛ فكلُّ جارحةٍ ستشهد عليك أو لك يومَ القيامة؛ فاجعلها شاهدةً لك بالطاعةِ لا عليك بالمعصية؛ فراقب الله في استعمالِ جوارحك؛ فلا تمشِ بها إلى حرام، ولا تبطش بها في باطل، ولا تنظر بها إلى محرّم، ولا تسمع بها ما يغضب الله؛ فمن حفظ جوارحه عن المعاصي شهدت له، ومن أطلقها في الحرامِ شهدت عليه؛ فاستحضر شهادةَ جوارحك؛ فيحملك ذلك على حفظها في طاعةِ الله."}},{"n":66,"reflection":{"text":"«ولو نشاء لطمسنا على أعينهم فاستبقوا الصراط فأنى يبصرون»، ولو نشاء لأذهبنا أبصارهم فتسابقوا إلى الطريقِ فكيف يبصرونه وقد طُمِست أعينهم؟ ففي هذا تقريرُ قدرةِ الله على أخذِ نعمةِ البصر؛ فاشكر نعمةَ البصرِ التي أنعم الله بها عليك، فلو شاء لطمسها، فاستعمل بصرك في طاعةِ الله شكرًا، ولا تكفر نعمةَ الله بالنظرِ إلى الحرام.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ البصرِ واستعمالُها في الطاعة."},"action":{"text":"اشكر نعمةَ البصرِ التي أنعم الله بها عليك، واعلم أنّ الله لو شاء لطمس على أعينك فأذهب بصرك «ولو نشاء لطمسنا على أعينهم فاستبقوا الصراط فأنى يبصرون»؛ فبصرك نعمةٌ من الله يستطيع أن يسلبها متى شاء؛ فاستعمل بصرك في طاعةِ الله شكرًا لهذه النعمة: انظر به في آياتِ الله، واقرأ به كتابه، وانظر به إلى ما ينفعك؛ ولا تكفر نعمةَ البصرِ باستعماله في النظرِ إلى الحرام؛ فغضَّ بصرك عمّا حرّم الله؛ فمن شكر نعمةَ البصرِ باستعماله في الطاعةِ حفظها الله عليه؛ ومن كفرها باستعماله في الحرامِ عرّضها للسلب؛ فاحفظ بصرك عن المحرّمات، واستعمله فيما يرضي الله؛ فالبصرُ أمانةٌ ستُسأل عنها؛ فاشكر الله على نعمةِ العينِ باستعمالها في طاعته؛ فكم من محرومٍ من البصر، وأنت تتمتّع به؛ فاحمد الله واستعمله في الخير."}},{"n":67,"reflection":{"text":"«ولو نشاء لمسخناهم على مكانتهم فما استطاعوا مضيا ولا يرجعون»، ولو نشاء لغيّرنا خلقهم ومسخناهم في أماكنهم فما استطاعوا مضيًّا إلى أمامهم ولا رجوعًا؛ ففي هذا تقريرُ قدرةِ الله على المسخِ والتغيير؛ فاشكر نعمةَ الله في سلامةِ خلقك وقوّتك، فلو شاء لمسخك وأعجزك، فاستعمل قوّتك وصحّتك في طاعةِ الله شكرًا، ولا تغترَّ بها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ سلامةِ الخلقِ والقوّة، واستعمالُها في الطاعة."},"action":{"text":"اشكر نعمةَ الله في سلامةِ خلقك وقوّتك وصحّتك، واعلم أنّ الله لو شاء لمسخك وغيّر خلقك وأعجزك عن الحركةِ فما استطعت مضيًّا ولا رجوعًا «ولو نشاء لمسخناهم على مكانتهم فما استطاعوا مضيا ولا يرجعون»؛ فسلامةُ خلقك وقوّتك نعمةٌ من الله يستطيع أن يسلبها متى شاء؛ فاستعمل قوّتك وصحّتك وسلامةَ جسدك في طاعةِ الله شكرًا لهذه النعمة؛ ولا تغترَّ بقوّتك وصحّتك فتستعملها في معصيةِ الله؛ فمن شكر نعمةَ الصحّةِ والقوّةِ باستعمالها في الطاعةِ حفظها الله عليه؛ ومن كفرها باستعمالها في المعصيةِ عرّضها للسلب؛ فبادر باستعمالِ صحّتك وقوّتك في الخيرِ قبل أن تُسلَبها؛ فالصحّةُ نعمةٌ يغبن فيها كثيرٌ من الناس؛ فاغتنم صحّتك قبل سقمك، وقوّتك قبل ضعفك؛ فاجعلها عونًا لك على طاعةِ الله وعبادته."}},{"n":68,"reflection":{"text":"«ومن نعمره ننكسه في الخلق أفلا يعقلون»، ومن نُطِل عمره نردّه إلى الضعفِ بعد القوّة والنقصِ بعد الكمال (كالطفولةِ في الشيخوخة)، أفلا يعقلون قدرةَ الله؟ ففي هذا آيةٌ في تغيّرِ الإنسانِ بالعمر؛ فاعتبر بتغيّرِ الإنسانِ من القوّةِ إلى الضعف، فمن ردّك إلى الضعفِ بعد القوّةِ قادرٌ على بعثك، فاعقل قدرةَ الله، ولا تغترَّ بقوّةِ الشباب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بتغيّرِ الإنسانِ من القوّةِ إلى الضعف، وعدمُ الاغترار."},"action":{"text":"اعتبر بتغيّرِ الإنسانِ وتنكيسه في الخلق، فمن أطال الله عمره ردّه إلى الضعفِ بعد القوّةِ والنقصِ بعد الكمال، حتى يعود كالطفلِ في ضعفه «ومن نعمره ننكسه في الخلق أفلا يعقلون»؛ فهذا آيةٌ على قدرةِ الله وحكمته؛ فاعقل قدرةَ الله الذي يقلّب الإنسانَ بين القوّةِ والضعف؛ ولا تغترَّ بقوّةِ شبابك وصحّتك، فهي إلى زوالٍ ونقص؛ فاستعمل قوّتك في طاعةِ الله قبل أن يأتيك الضعف؛ ومن قدر على تنكيسك بعد القوّةِ قادرٌ على بعثك بعد الموت؛ فاعتبر بهذا لتوقن بالبعثِ وقدرةِ الله؛ فتأمّل أطوارك: ضعفٌ ثم قوّةٌ ثم ضعف؛ فلا تتكبّر، وتواضع لله؛ فمن اعتبر بتغيّرِ الأعمارِ عرف عجزه وقدرةَ خالقه؛ فاغتنم قوّتك في الطاعةِ قبل ضعفِ الشيخوخة."}}]},{"title":"القرآنُ ذكرٌ لا شعر، وآياتُ الأنعام، وبراهينُ البعثِ وختامُ «كن فيكون»","range":[69,83],"theme":"تنزيهُ النبيِّ عن الشعرِ وأنّ القرآنَ ذكرٌ ينذر الأحياء، ونعمةُ الأنعامِ المسخّرة، وعجزُ الآلهةِ عن النصر، وبراهينُ البعثِ: الخلقُ من نطفة، والنارُ من الشجرِ الأخضر، وخلقُ السماواتِ والأرض، وأنّ أمرَه «كن فيكون»، وختامٌ بتسبيحِ من بيده ملكوتُ كلِّ شيءٍ وإليه المرجع","verses":[{"n":69,"reflection":{"text":"«وما علمناه الشعر وما ينبغي له إن هو إلا ذكر وقرآن مبين»، وما علّمنا محمدًا الشعرَ وما يليق به أن يكون شاعرًا، ما هو إلا ذكرٌ وقرآنٌ مبين؛ ففي هذا تنزيهُ النبيِّ عن الشعرِ وتقريرُ أنّ القرآنَ ذكرٌ ووحي؛ فاعلم أنّ القرآنَ ليس شعرًا ولا كلامَ بشر، بل ذكرٌ وقرآنٌ مبينٌ من عند الله، فعظّمه وميّزه عن كلامِ الخلق، فهو وحيٌ لا شعر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ أنّ القرآنَ ذكرٌ ووحيٌ لا شعر، وتعظيمُه."},"action":{"text":"اعلم أنّ القرآنَ ليس شعرًا ولا كلامَ بشر، فما علّم الله نبيَّه ﷺ الشعرَ وما يليق به أن يكون شاعرًا، بل القرآنُ ذكرٌ وقرآنٌ مبينٌ من عند الله «وما علمناه الشعر وما ينبغي له إن هو إلا ذكر وقرآن مبين»؛ فميّز القرآنَ عن كلامِ الخلقِ كلِّه، فهو وحيٌ إلهيٌّ لا شعرٌ ولا نثرُ بشر؛ فعظّمه في قلبك، وتلقَّه بالإجلالِ والإذعان؛ ولا تسوّه بكلامِ الناسِ مهما بلغ من البلاغة؛ فالقرآنُ فوق كلامِ البشرِ لأنه كلامُ الله؛ فاجعله ذكرك ونورك؛ فمن عرف أنّ القرآنَ وحيٌ من الله عظّمه وعمل به؛ فأقبل عليه تلاوةً وتدبّرًا وعملًا؛ فهو ذكرٌ يحيي القلوب، وقرآنٌ مبينٌ يهدي إلى الحق؛ فلا تعامله كسائرِ الكلام، بل كوحيٍ من ربِّ العالمين؛ فعظّمه، واتّبعه، واجعله إمامك."}},{"n":70,"reflection":{"text":"«لينذر من كان حيا ويحق القول على الكافرين»: أُنزِل القرآنُ لينذر من كان حيَّ القلبِ يقظانه، ولتقوم الحجّةُ فيحقَّ العذابُ على الكافرين المعرضين؛ ففي هذا أنّ المنتفعَ بالإنذارِ حيُّ القلب؛ فاحرص على حياةِ قلبك لتنتفع بإنذارِ القرآن، فالقرآنُ ينذر أحياءَ القلوب، فمن أحيا قلبه بالإيمانِ انتفع بالقرآن، ومن مات قلبه حُرِم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على حياةِ القلبِ للانتفاعِ بإنذارِ القرآن."},"action":{"text":"احرص على حياةِ قلبك بالإيمانِ والذكرِ والطاعة، لتنتفع بإنذارِ القرآنِ وموعظته، فإنّ القرآنَ إنما ينذر ويهدي من كان حيَّ القلبِ يقظانه، وتقوم به الحجّةُ على الكافرين المعرضين «لينذر من كان حيا ويحق القول على الكافرين»؛ فالقلبُ الحيُّ ينتفع بالقرآنِ ويتّعظ به، والقلبُ الميّتُ يُعرِض عنه فتقوم عليه الحجّة؛ فتعاهد قلبك بما يحييه: من تلاوةِ القرآنِ وتدبّره، وذكرِ الله، والطاعة، والتوبة؛ واحذر ما يميت القلبَ: من الكفرِ والغفلةِ والمعاصي؛ فمن أحيا الله قلبه انتفع بالقرآنِ واهتدى به، ومن أماته أعرض عنه فحُقّ عليه القول؛ فاجعل قلبك حيًّا واعيًا متفاعلًا مع القرآن؛ فكلّما تلوت آيةً أو سمعت موعظةً فتفاعل معها بقلبك وعملك؛ فالقرآنُ حياةٌ لأحياءِ القلوب، وحجّةٌ على موتاها."}},{"n":71,"reflection":{"text":"«أولم يروا أنا خلقنا لهم مما عملت أيدينا أنعاما فهم لها مالكون»: أولم يروا أنا خلقنا لهم ممّا تفرّدنا بخلقه أنعامًا (إبلًا وبقرًا وغنمًا) فهم لها مالكون منتفعون؟ ففي هذا تعدادُ نعمةِ الأنعام؛ فتأمّل نعمةَ الله في خلقِ الأنعامِ لك وتمليكها إياك، واشكره عليها، فمن خلق لك الأنعامَ وملّكك إياها يستحقّ شكرك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في نعمةِ الأنعامِ المخلوقةِ لك، وشكرُ الله عليها."},"action":{"text":"تأمّل نعمةَ الله في خلقِ الأنعامِ (الإبلِ والبقرِ والغنم) لك، وتمليكك إياها لتنتفع بها، فهي ممّا تفرّد الله بخلقه «أولم يروا أنا خلقنا لهم مما عملت أيدينا أنعاما فهم لها مالكون»؛ فاشكر الله على هذه النعمةِ العظيمة، فقد سخّر لك هذه الأنعامَ وجعلك مالكًا لها منتفعًا بها؛ فلولا خلقُ الله لها وتذليلُها لك ما ملكتها ولا انتفعت بها؛ فاجعل هذه النعمةَ سبيلًا للشكرِ والاعتبار؛ فكلّما رأيت أنعامًا أو انتفعت بها فتذكّر منعمها واشكره؛ فمن تأمّل نعمَ الله المسخّرةَ له وشكرها زاده الله؛ فاجعل النعمَ داعيةً للشكرِ لا للغفلة؛ فالله خلق لك ما في الأرضِ لتشكره وتعبده؛ فقابل نعمه بالحمدِ والطاعة."}},{"n":72,"reflection":{"text":"«وذللناها لهم فمنها ركوبهم ومنها يأكلون»، وذلّلنا الأنعامَ لهم وسخّرناها فمنها ما يركبونه ومنها ما يأكلون؛ ففي هذا تعدادُ منافعِ الأنعام؛ فتأمّل نعمةَ الله في تذليلِ الأنعامِ لك للركوبِ والأكل، واشكره عليها، فمن ذلّل لك هذه المخلوقاتِ القويّةَ لتنتفع بها يستحقّ شكرك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في تذليلِ الأنعامِ للركوبِ والأكل، وشكرُ الله."},"action":{"text":"تأمّل نعمةَ الله في تذليلِ الأنعامِ لك وتسخيرها، مع قوّتها وكبرها، فمنها ما تركبه وتحمل عليه، ومنها ما تأكل من لحمه «وذللناها لهم فمنها ركوبهم ومنها يأكلون»؛ فلولا تذليلُ الله لها لما استطعت ركوبها ولا الانتفاعَ بها؛ فتأمّل كيف ذلّل الله لك هذه المخلوقاتِ القويّةَ التي لو شاءت لامتنعت عليك؛ فاشكر الله على هذه النعمةِ العظيمة؛ فكلّما ركبت دابّةً أو أكلت من لحمِ الأنعامِ فتذكّر منعمها واشكره؛ فمن تأمّل نعمَ الله المسخّرةَ له وشكرها زاده الله؛ فاجعل هذه النعمَ عونًا لك على طاعةِ الله لا على معصيته؛ فالله ذلّل لك ما في الأرضِ لتشكره وتعبده وتستعين به على طاعته؛ فقابل نعمه بالشكرِ والحمدِ والطاعة، لا بالكفرانِ والغفلة."}},{"n":73,"reflection":{"text":"«ولهم فيها منافع ومشارب أفلا يشكرون»، ولهم في الأنعامِ منافعُ (كالصوفِ والوبرِ والجلد) ومشاربُ (كاللبن)، أفلا يشكرون الله على ذلك؟ ففي هذا الحثُّ على شكرِ نعمِ الأنعام؛ فاشكر الله على منافعِ الأنعامِ ومشاربها، فمن جعل لك فيها منافعَ ومشاربَ يستحقّ شكرك، فقابل النعمَ بالشكرِ لا بالغفلة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ الله على منافعِ الأنعامِ ومشاربها."},"action":{"text":"اشكر الله على ما في الأنعامِ من منافعَ كثيرةٍ (كالصوفِ والوبرِ والجلودِ والأثمان) ومشاربَ نافعةٍ (كاللبن) «ولهم فيها منافع ومشارب أفلا يشكرون»؛ فقد جعل الله لك في هذه الأنعامِ منافعَ متعدّدةً تنتفع بها في حياتك؛ فقابل هذه النعمَ بالشكرِ لا بالغفلةِ والكفران؛ فكلّما انتفعت بمنفعةٍ من الأنعامِ أو شربت من لبنها فتذكّر منعمها واشكره؛ فقلّةُ الشكرِ نقصٌ يُذَمّ، وكثرتُه سببٌ للمزيد؛ فمن شكر الله على نعمه حفظها وزاده، ومن كفرها عرّضها للزوال؛ فلا تكن من الغافلين الذين يتنعّمون بنعمِ الله ولا يشكرونها؛ بل كن من الشاكرين الذاكرين لفضلِ الله؛ فالشكرُ قيدُ النعمِ الموجودةِ وصيدُ المفقودة؛ فاجعل حمدَ الله وشكره على نعمه دأبك في كلِّ حين؛ فالله يحبّ الشاكرين ويزيدهم من فضله."}},{"n":74,"reflection":{"text":"«واتخذوا من دون الله آلهة لعلهم ينصرون»، واتّخذ المشركون من دونِ الله آلهةً يرجون أن ينصروهم؛ ففي هذا بطلانُ رجاءِ النصرِ من غيرِ الله؛ فلا ترجُ النصرَ إلا من الله، فالمعبوداتُ من دونِ الله لا تنصر، فمن اتّخذ من دونِ الله ناصرًا خُذِل، فاطلب النصرَ من الله وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ رجاءِ النصرِ من غيرِ الله، وطلبُه منه وحده."},"action":{"text":"لا ترجُ النصرَ ولا العونَ إلا من الله وحده، ولا تتّخذ من دونه آلهةً أو معبوداتٍ ترجو نصرها، كما فعل المشركون الذين اتّخذوا من دونِ الله آلهةً رجاءَ نصرها «واتخذوا من دون الله آلهة لعلهم ينصرون»؛ فالمعبوداتُ من دونِ الله عاجزةٌ لا تنصر عابديها بل تخذلهم؛ فمن اتّخذ من دونِ الله ناصرًا خُذِل وضاع؛ فاطلب النصرَ والعونَ من الله القادرِ وحده؛ ولا تعلّق قلبك بمخلوقٍ في جلبِ نفعٍ أو دفعِ ضرّ؛ فالله وحده الناصرُ المعين؛ فمن استنصر بالله نصره، ومن استنصر بغيره خُذِل؛ فاجعل توكّلك واستنصارك بالله وحده؛ فلا ناصرَ إلا هو، ولا معينَ سواه؛ فحقّق التوحيدَ في طلبِ النصرِ والعون؛ فالعزّةُ والنصرُ بيدِ الله يؤتيهما من يشاء."}},{"n":75,"reflection":{"text":"«لا يستطيعون نصرهم وهم لهم جند محضرون»: لا تستطيع تلك الآلهةُ نصرَ عابديها، بل العابدون لها جندٌ محضَرون في النارِ معها؛ ففي هذا عجزُ المعبوداتِ عن النصرِ وسوءُ عاقبةِ عابديها؛ فلا تعبد ما لا ينصرك، فالمعبوداتُ من دونِ الله عاجزةٌ عن النصر، وعابدوها معها في النار، فأخلص العبادةَ لله الناصر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ عجزِ المعبوداتِ عن النصر، وإخلاصُ العبادةِ لله."},"action":{"text":"اعلم أنّ المعبوداتِ من دونِ الله عاجزةٌ عن نصرِ عابديها، بل هي وعابدوها جميعًا محضَرون في النار «لا يستطيعون نصرهم وهم لهم جند محضرون»؛ فكيف تعبد من لا يستطيع نصرك بل يكون سببًا لهلاكك؟ فأخلص العبادةَ لله الناصرِ القادرِ وحده؛ ولا تعبد عاجزًا لا ينفع ولا ينصر؛ فمن عبد غيرَ الله خُذِل وكان معبوده وبالًا عليه؛ فاصرف عبادتك ودعاءك وتوكّلك ورجاءك إلى الله وحده؛ فهو الناصرُ المعينُ الذي بيده النفعُ والضرّ؛ فحقّق التوحيدَ الخالص؛ فالعبادةُ حقٌّ للناصرِ القادر، لا للعاجزِ الذي لا يملك شيئًا؛ فمن أخلص لله نصره الله، ومن أشرك خذله معبوده وكان معه في العذاب؛ فاجعل عبادتك كلَّها لله وحده."}},{"n":76,"reflection":{"text":"«فلا يحزنك قولهم إنا نعلم ما يسرون وما يعلنون»: فلا يحزنك يا محمدُ قولُ المكذّبين وطعنهم، إنا نعلم ما يسرّون وما يعلنون فنجازيهم؛ ففي هذا تسليةُ النبيِّ وأنّ الله عليمٌ بأحوالهم؛ فلا يحزنك أذى الناسِ وطعنهم، فالله يعلم ما يسرّون وما يعلنون، فكِل أمرهم إليه، فمن علم أنّ الله محيطٌ بكلِّ شيءٍ اطمأنَّ ولم يحزن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الحزنِ من أذى الناسِ، فالله عليمٌ بأحوالهم."},"action":{"text":"لا يحزنك أذى الناسِ وطعنهم وقولهم فيك أو في الحقّ، فإنّ الله يعلم ما يسرّون وما يعلنون من الطعنِ والكيد، وهو مجازيهم على ذلك «فلا يحزنك قولهم إنا نعلم ما يسرون وما يعلنون»؛ فكِل أمرهم إلى الله العليمِ بأحوالهم؛ فلا تحمل همَّ أذاهم ولا يشغلك عن طريقك؛ فمن علم أنّ الله محيطٌ بكلِّ شيء، مطّلعٌ على ما يسرّه أعداؤه ويعلنونه، اطمأنَّ قلبه ولم يحزن؛ فامضِ في دعوتك وعملك، غيرَ مكترثٍ بأذى المبطلين؛ فالله كافيك ومنتقمٌ لك؛ فاجعل عزاءك أنّ الله يعلم صدقك ويعلم كيدهم؛ فلا تحزن على ما يقولون، ولا يوهنك أذاهم؛ بل توكّل على الله، واثقًا بعلمه وكفايته؛ فمن توكّل على الله كفاه أذى الخلق؛ فاصبر واحتسب، ودع أمرهم لله العليم."}},{"n":77,"reflection":{"text":"«أولم ير الإنسان أنا خلقناه من نطفة فإذا هو خصيم مبين»: أولم ير الإنسانُ أنا خلقناه من نطفةٍ (ماءٍ مهين) فإذا هو خصيمٌ مبينٌ يجادل في البعث؟ ففي هذا التذكيرُ بأصلِ الإنسانِ الضعيفِ وإنكارُ جداله في قدرةِ الله؛ فتذكّر أصلك من نطفةٍ لتتواضع ولا تجادل في قدرةِ الله، فمن كان أصله نطفةً كيف يكابر خالقه؟ فتواضع وأذعن لقدرةِ الله على البعث.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكّرُ الأصلِ الضعيف، وعدمُ المكابرةِ في قدرةِ الله."},"action":{"text":"تذكّر أصلك: خلقك الله من نطفةٍ (ماءٍ مهينٍ ضعيف)، ثم صرت خصيمًا مبينًا تجادل وتكابر حتى في قدرةِ الله على البعث «أولم ير الإنسان أنا خلقناه من نطفة فإذا هو خصيم مبين»؛ فكيف تكابر خالقك وأصلك نطفةٌ حقيرة؟ فتواضع لله واعرف قدرك؛ ولا تجادل في قدرةِ الله على البعثِ أو غيره؛ فمن خلقك من نطفةٍ قادرٌ على إعادتك بعد الموت؛ فاستحضر ضعفَ أصلك لتتواضع وتذعن لقدرةِ الله؛ فالمكابرةُ في قدرةِ الله جهلٌ وكبر؛ فمن عرف أصله الضعيف لان قلبه وأذعن لخالقه؛ فلا تجعل من نفسك خصيمًا مجادلًا في الحقِّ الواضح؛ بل كن مذعنًا متواضعًا مسلّمًا لقدرةِ الله وحكمته؛ فالتواضعُ يليق بمن أصله نطفةٌ ومآله جيفة؛ فأذعن للحقِّ، ولا تكابر في قدرةِ الله على كلِّ شيء."}},{"n":78,"reflection":{"text":"«وضرب لنا مثلا ونسي خلقه قال من يحيي العظام وهي رميم»، وضرب الإنسانُ لنا مثلًا في إنكارِ البعث، ونسي خلقه الأوّلَ من العدم، قال: من يحيي العظامَ وهي باليةٌ متفتّتة؟ ففي هذا إنكارُ المشركِ للبعثِ مع نسيانِ خلقه الأوّل؛ فلا تنسَ خلقك الأوّلَ من العدمِ فتنكر البعث، فمن خلقك أوّلًا قادرٌ على إعادتك، فالبعثُ أهونُ من البدء، فأيقن به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ نسيانِ الخلقِ الأوّلِ الدالِّ على القدرةِ على البعث."},"action":{"text":"لا تنسَ خلقك الأوّلَ من العدمِ فتنكر البعثَ وتستبعده، كما فعل المشركُ الذي ضرب المثلَ في إنكارِ البعثِ ونسي خلقه الأوّل، فقال: «من يحيي العظام وهي رميم»؛ فمن خلقك أوّلًا من العدمِ ومن نطفةٍ قادرٌ على إعادتك بعد أن تصير عظامًا باليةً؛ فالإعادةُ أهونُ من البدء، وكلاهما على الله يسير؛ فتذكّر خلقك الأوّلَ لتوقن بالبعث؛ فمن تأمّل بدء خلقه أيقن بقدرةِ الله على إعادته؛ فلا تكن كالمنكرِ الذي نسي بدايته فأنكر نهايته؛ بل استدلَّ بالخلقِ الأوّلِ على البعثِ الآخر؛ فرسّخ يقينك بالبعثِ بالنظرِ في خلقك الأوّل؛ فمن أنشأك من العدمِ قادرٌ على أن يعيدك؛ فأيقن بالبعثِ، واعمل له؛ فالبعثُ حقٌّ، ومن أنكره ناسٍ لأصله جاهلٌ بقدرةِ خالقه."}},{"n":79,"reflection":{"text":"«قل يحييها الذي أنشأها أول مرة وهو بكل خلق عليم»: قل: يحيي العظامَ الباليةَ الذي أنشأها أوّلَ مرّةٍ من العدم، وهو بكلِّ خلقٍ عليم؛ ففي هذا الجوابُ القاطعُ على منكرِ البعث؛ فأيقن بأنّ الذي خلقك أوّلًا قادرٌ على إحيائك بعد الموت، فهو بكلِّ خلقٍ عليمٌ لا يعجزه شيء، فالبعثُ حقٌّ لا شكَّ فيه، فاستعدَّ له.","source":"تفسير السعدي","grade":"ma'thur"},"names":["العليم"],"heart_state":{"text":"اليقينُ بأنّ خالقك أوّلًا قادرٌ على إحيائك، وهو بكلِّ خلقٍ عليم."},"action":{"text":"أيقن بأنّ الذي يحيي العظامَ الباليةَ هو الذي أنشأها وخلقها أوّلَ مرّةٍ من العدم، وهو بكلِّ خلقٍ عليمٌ لا يخفى عليه شيءٌ من أجزائها ولو تفرّقت «قل يحييها الذي أنشأها أول مرة وهو بكل خلق عليم»؛ فمن خلقك أوّلًا من العدمِ قادرٌ على إعادتك بعد الموتِ والبلى؛ فهو عليمٌ بكلِّ خلقٍ، يعلم أين تفرّقت أجزاؤك وكيف يجمعها؛ فالبعثُ حقٌّ لا شكَّ فيه؛ فرسّخ يقينك به؛ واستعدَّ له بالإيمانِ والعملِ الصالح؛ فمن أيقن بقدرةِ الله على البعثِ عمل له؛ فلا يدخلنّ قلبك شكٌّ في البعث؛ فالذي بدأ الخلقَ قادرٌ على إعادته، عليمٌ بتفاصيله؛ فاجعل هذا اليقينَ راسخًا في قلبك؛ فيحملك على الاستعدادِ ليومِ البعثِ والحساب؛ فالبعثُ آتٍ، والحسابُ واقع؛ فبادر بالعملِ الصالحِ قبل فواتِ الأوان."}},{"n":80,"reflection":{"text":"«الذي جعل لكم من الشجر الأخضر نارا فإذا أنتم منه توقدون»: الله الذي جعل لكم من الشجرِ الأخضرِ الرطبِ نارًا فإذا أنتم منه توقدون؛ ففي هذا آيةٌ في إخراجِ النارِ من الشجرِ الأخضرِ دليلًا على القدرة؛ فتأمّل قدرةَ الله في إخراجِ النارِ (اليابسةِ الحارّة) من الشجرِ الأخضر (الرطبِ البارد)، فمن جمع بين الضدّين قادرٌ على إحياءِ الموتى، فاعتبر واشكر نعمةَ النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في إخراجِ النارِ من الشجرِ الأخضرِ دليلًا على القدرة."},"action":{"text":"تأمّل قدرةَ الله في إخراجِ النارِ (وهي يابسةٌ حارّة) من الشجرِ الأخضرِ (وهو رطبٌ بارد)، فإذا أنتم منه توقدون «الذي جعل لكم من الشجر الأخضر نارا فإذا أنتم منه توقدون»؛ فمن جمع بين الضدّين (النارِ والماءِ) في الشجرِ الأخضر، وأخرج الحارَّ من البارد، قادرٌ على إحياءِ الموتى وإخراجِ الحيِّ من الميّت؛ فاستدلَّ بهذه الآيةِ على قدرةِ الله على البعث؛ واشكر نعمةَ النارِ التي بها منافعُ كثيرةٌ في حياتك؛ فتأمّل بديعَ صنعِ الله وقدرته؛ فكلّما أوقدت نارًا فتذكّر قدرةَ خالقها الذي أخرجها من الشجرِ الأخضر؛ فمن تأمّل آياتِ الله في الكونِ ازداد يقينًا بقدرته على البعثِ وعظّمه وشكره؛ فاجعل نظرك في آياتِ الله سبيلًا لتقويةِ إيمانك بالبعثِ وشكرِ نعمه؛ فالله على كلِّ شيءٍ قدير."}},{"n":81,"reflection":{"text":"«أوليس الذي خلق السماوات والأرض بقادر على أن يخلق مثلهم بلى وهو الخلاق العليم»: أوليس الذي خلق السماواتِ والأرضَ (وهما أعظمُ من الناس) بقادرٍ على أن يخلق مثلهم (يعيدهم)؟ بلى وهو الخلّاقُ العليم؛ ففي هذا برهانُ البعثِ بالأولى؛ فأيقن بأنّ من خلق السماواتِ والأرضَ العظيمتين قادرٌ على إعادتك، فمن قدر على الأعظمِ قدر على الأدنى، فالبعثُ حقٌّ، وهو الخلّاقُ العليم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الخلاق","العليم"],"heart_state":{"text":"اليقينُ بالبعثِ بالأولى، فمن خلق السماواتِ قادرٌ على إعادتك."},"action":{"text":"أيقن بأنّ الذي خلق السماواتِ والأرضَ (وهما أعظمُ خلقًا من الناس) قادرٌ على أن يخلق مثلهم ويعيدهم بعد الموت «أوليس الذي خلق السماوات والأرض بقادر على أن يخلق مثلهم بلى وهو الخلاق العليم»؛ فمن قدر على خلقِ الأعظمِ (السماواتِ والأرض) فهو على خلقِ الأدنى (إعادةِ الإنسان) أقدر؛ فهذا برهانٌ قاطعٌ على البعثِ بالأولى؛ فلا تستبعد البعثَ ولا تشكّ فيه؛ فهو الخلّاقُ الذي يخلق ما يشاء، العليمُ الذي أحاط بكلِّ شيء؛ فرسّخ يقينك بالبعثِ بالنظرِ في خلقِ السماواتِ والأرض؛ فمن خلق هذا الكونَ العظيمَ لا يعجزه إعادةُ خلقك؛ فاستعدَّ للبعثِ بالعملِ الصالح؛ فالبعثُ حقٌّ، والحسابُ آتٍ؛ فمن أيقن بقدرةِ الخلّاقِ العليمِ على البعثِ عمل له؛ فاجعل هذا البرهانَ مقوّيًا ليقينك بالبعثِ واستعدادك له."}},{"n":82,"reflection":{"text":"«إنما أمره إذا أراد شيئا أن يقول له كن فيكون»: إنما أمرُ الله إذا أراد شيئًا أن يقول له: كن، فيكون في الحال بلا مؤونةٍ ولا تأخّر؛ ففي هذا تقريرُ كمالِ قدرةِ الله ونفوذِ مشيئته؛ فأيقن بكمالِ قدرةِ الله، فما أراده كان بكلمةٍ واحدة، فلا يعجزه شيء، ولا يستبعد شيءٌ من قدرته، فاطلب حاجتك من القادرِ الذي يقول للشيءِ كن فيكون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بكمالِ قدرةِ الله، فما أراده كان بكلمةِ «كن»."},"action":{"text":"أيقن بكمالِ قدرةِ الله ونفوذِ مشيئته، فإنما أمرُه إذا أراد شيئًا أن يقول له: كن، فيكون في الحالِ بلا مؤونةٍ ولا تأخّرٍ ولا معالجة «إنما أمره إذا أراد شيئا أن يقول له كن فيكون»؛ فما أراده الله كان بكلمةٍ واحدة، وما لم يشأه لم يكن؛ فلا يعجزه شيء، ولا يستبعد شيءٌ من قدرته: لا البعثُ ولا النصرُ ولا الفرجُ ولا الرزق؛ فاطلب حاجتك من القادرِ الذي يقول للشيءِ: كن فيكون؛ فمن أيقن بكمالِ قدرةِ الله وثق به وتوكّل عليه، ولم يستبعد فرجه ولا نصره ولا عطاءه؛ فاجعل يقينك بقدرةِ الله راسخًا؛ فبه يقوى توكّلك ويطمئنّ قلبك؛ فما استعصى على غيره فهو على الله يسير؛ فادعُ الله واثقًا بقدرته؛ فهو الذي إذا أراد شيئًا قال له: كن فيكون؛ فلا شيءَ يعجزه، وكلُّ شيءٍ طوعُ مشيئته؛ فعلّق قلبك بالقادرِ على كلِّ شيء."}},{"n":83,"reflection":{"text":"«فسبحان الذي بيده ملكوت كل شيء وإليه ترجعون»: فتنزّه الله الذي بيده ملكُ كلِّ شيءٍ وتدبيرُه، وإليه ترجعون جميعًا للحساب؛ ففي هذا ختمُ السورةِ بتسبيحِ الله وتقريرِ ملكِه والمعاد؛ فسبّح الله الذي بيده ملكوتُ كلِّ شيء، واستعدَّ لرجوعك إليه، فمن كان ملكوتُ كلِّ شيءٍ بيده فهو المستحقُّ للعبادةِ والتعظيم، وإليه المرجعُ والمصير، فاعمل لذلك اليوم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الملك"],"heart_state":{"text":"تسبيحُ الله الذي بيده ملكوتُ كلِّ شيء، والاستعدادُ للمعاد."},"action":{"text":"سبّح الله ونزّهه وعظّمه، فهو الذي بيده ملكوتُ كلِّ شيءٍ وملكُه وتدبيره، وإليه ترجعون جميعًا للحساب «فسبحان الذي بيده ملكوت كل شيء وإليه ترجعون»؛ فمن كان ملكوتُ كلِّ شيءٍ بيده فهو وحده المستحقُّ للعبادةِ والتعظيمِ والتسبيح؛ فاجعل لسانك رطبًا بتسبيحِ الله وتعظيمه؛ واستعدَّ لرجوعك إليه بالإيمانِ والعملِ الصالحِ والتوبة؛ فاستحضر أنّ ملكَ كلِّ شيءٍ بيدِ الله، وأنك راجعٌ إليه للحساب؛ فيحملك ذلك على تعظيمِ الله وعبادته والاستعدادِ للقائه؛ فمن عظّم الله وسبّحه وأيقن بالرجوعِ إليه عمل لذلك اليوم؛ فاختم أمرك بتسبيحِ الله وتعظيمه والاستعدادِ للمعاد؛ فله الملكُ كلُّه، وإليه المرجعُ والمصير؛ فاعبده وحده، وسبّحه، واعمل ليومِ لقائه؛ فهو الذي بيده كلُّ شيء، وإليه تُرجَع الأمورُ كلُّها."}}]}],"coverage":{"covered":83,"total":83}};
